INSERT INTO `_koKR_stage_npc_text_locale` (`ID`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(1, '반갑습니다, $n.', '반갑습니다, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2, '반갑습니다, $n. 어떻게 도와 드릴까요?', '반갑습니다, $n. 어떻게 도와 드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3, '안녕하신가요, 스톰윈드의 시민이여. 내게 하실 말씀이 없으시면 가던 길을 가 주셨으면 합니다만…', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4, '나는 오직 왕을 섬길 뿐이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5, '계속 가시오. 여기는 볼 것이 없어.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(18, '내 곁에 있으시오, $N. 우리가 도움이 필요할지도 모르겠오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(24, '아, $n! 당신이 온다는 소식을 작은 새에게 전해 들었소.$B$B아비아나 님은 이렇게 소식을 전달하신다오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(34, '어떤 전문 기술을 배우려고 하십니까?', '어떤 전문 기술을 배우려고 하십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(42, '데스윙이 돌아왔습니다. 그는 그림 바톨과 고원의 여러 지역을 손에 넣었지요. 데스윙을 막기엔 제가 너무 약하다는 자괴감이 들 정도입니다.$B$B곧 우리 여왕님께서 도착하실 겁니다. 그리고 우리는, 한때 대지의 수호자였던 그자를 물리칠 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(48, '도움이 필요하십니까?', '도움이 필요하십니까?', '도움이 필요하십니까?', '도움이 필요하십니까?', '도움이 필요하십니까?', '도움이 필요하십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(68, '반갑습니다, $n.', '반갑습니다, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(82, '용아귀 부족을 도우면 충분한 보상을 얻을 걸세, $c|1이여;여;.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(107, '뭐야? 이 멍청한 녀석아', '뭐야? 이 멍청한 녀석아', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(134, '호드 전투 기계가 당신을 필요로 합니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(141, '나는 지도자의 책무와 역할에 아직 익숙하지 않네. 나크랄이 이렇게 반항할 줄 미리 눈치챘어야 했는데, 대비는커녕 그가 저지른 일을 수습하고 있다니.$B$B가로쉬 헬스크림은 어떻게 호드를 이끄는지 궁금하군. 호드처럼 다양한 세력이 모인 집단을 이끄는 걸 보면 엄청난 힘의 소유자일 테지... 그를 좀 더 자세히 알고 싶군.', '나는 지도자의 책무와 역할에 아직 익숙하지 않네. 나크랄이 이렇게 반항할 줄 미리 눈치챘어야 했는데, 대비는커녕 그가 저지른 일을 수습하고 있다니.$B$B가로쉬 헬스크림은 어떻게 호드를 이끄는지 궁금하군. 호드처럼 다양한 세력이 모인 집단을 이끄는 걸 보면 엄청난 힘의 소유자일 테지... 그를 좀 더 자세히 알고 싶군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(153, '어이, 친구, 잘 지내지?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(158, '반가워요, $c님.$B$B하이잘은 불타오르고 제가 평생을 바쳐 지켜온 세상은 흔적도 없이 사라질 위기에 처해 있어요.$B$B대답해 주세요. 타이러스 블랙혼이라는 이름을 들어본 적이 있나요?', '반가워요, $c님.$B$B하이잘은 불타오르고 제가 평생을 바쳐 지켜온 세상은 흔적도 없이 사라질 위기에 처해 있어요.$B$B대답해 주세요. 타이러스 블랙혼이라는 이름을 들어본 적이 있나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(166, '여행으로 지치신 분이시여, 저희 여관에 오신것을 환영합니다! 무엇을 도와 드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(185, '원하시면 여기서 휴식을 취하셔도 됩니다. 대지의 사원은 이제 안전합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(194, '여행으로 지치신 분이시여, 저희 여관에 오신것을 환영합니다! 무엇을 도와 드릴까요?', '여행으로 지치신 분이시여, 저희 여관에 오신것을 환영합니다! 무엇을 도와 드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(197, '북녘골의 시민이여... 당신 체격이 꽤 좋은 분이로군요. 여기 경비가 좀 부실한데 좀 도와주실 수 있습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(215, '대지의 수호자, 그리고 그의 아이들이 언젠가는 죄악에서 구원되리란 희망을 오랫동안 버리지 않았습니다. 하지만, 어느 순간 우리도 깨닫고, 인정할 수밖에 없었지요. 검은용들이 이 세상에 행한 파괴는 어떤 속죄로도 보상할 수 없다는 사실을 말입니다.$B$B그래서 어쩔 수 없이 이 일에 끼어들게 되었습니다.', '대지의 수호자, 그리고 그의 아이들이 언젠가는 죄악에서 구원되리란 희망을 오랫동안 버리지 않았습니다. 하지만, 어느 순간 우리도 깨닫고, 인정할 수밖에 없었지요. 검은용들이 이 세상에 행한 파괴는 어떤 속죄로도 보상할 수 없다는 사실을 말입니다.$B$B그래서 어쩔 수 없이 이 일에 끼어들게 되었습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(225, '내 평생에, $r, 이런걸 본 적이 없네요…', NULL, '이곳에서 전투를 치르기에는 장비가 너무 열악하다네.$b$b전투에 대비해야 할 텐데...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(246, '나가서 저 바위 트로그들을 다시 땅속으로 돌려 보내세, $r 친구!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(247, '자네가 최전선에 가 주어야겠네, $n.$B$B자네라면 상황을 반전시킬 수 있을 거야. 우린 바위 트로그들을 박멸할 것이네.$B$B오어맨틀 국왕 폐하를 구출해야 하네!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(248, '<투덜대며 코웃음 치는 클레이>$B$B하여간 요즘 젊은 것들은.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(328, '반갑습니다, $n.', '반갑습니다, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(384, '반갑습니다, $n.', '반갑습니다, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(401, '맹금의 봉우리에 있는 와일드해머 드워프들도 빠른 그리핀들을 가지고 있긴 하지만 과연 그 그리핀들이 대용광로의 열기를 견뎌낼 수 있을까요? 어림도 없죠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(447, '시험의 골짜기에서는 칼림도어에서 가장 허약한 자라도 호드와 어깨를 나란이 하고 싸울 수 있을 만한 강력한 전사로 단련시켜 주지. 우리의 시험을 통과하지 못한 자들은 이글거리는 사막의 태양 아래서 타죽게 된다고.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(518, '할 일이 많아, 아주 많다고! 조합에서 마감 기한을 줬는데, 절대 어기고 싶지 않은 기한이란 말이지!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(519, '원래 스팀휘들의 벌목기 개발 프로젝트를 감독했었지만, 지난달에 독립했어. 그러니까 물건 대주는 모두에게 찍혀버렸지. 더 나쁜 건, 개발 작업이 아직 시작도 못 했다는 거야. $n, 자네 손을 좀 빌렸으면 하는 데 말이지!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(520, '보라고, 투자개발회사의 새 벌목기가 내 최신 벌목기보다 더 뛰어나단 말이야! 손도 바꿀 수 있고 조종 손잡이도 훨씬 간편해!$B$B상부에서 엄격하게 최종 기한을 정해 놓았는데 내 부하 직원들과 나로선 아무것도 할 수가 없었어.$B$B제대로 작동하는 게 하나도 없었으니까. 그래서, 결국 저들의 원형을 하나 "빌리기로" 했지. 위즐크랭크에게 진흙 늪으로 가서 하나 훔쳐 오라고 시켰는데 아직까지 돌아오지 않는군!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(521, '유령울음늑대를 해치우다니! 아주 훌륭하십니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(522, '더 가까이 오게, 젊은이. 한창때는 사냥감의 심장 뛰는 소리도 들리더니만 지금은 큰 소리로 말해야 겨우 알아들을 수가 있다네, 허허.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(523, '난 아주 오랫동안 이 평원을 누벼왔지. 거대한 짐승들도 사냥해 왔고. 한 번도 패한 적은 없었네... 유령울음늑대를 상대하기 전까지는 말이야.$B$B아주 오래전, 이 거대한 유령울음늑대는 타우렌과 함께 불타는 군단에 맞서 용감히 싸운 적도 있었다네. 하지만 악마와 싸우다 살이 찢겨 나가는 심각한 부상을 입었고 그 부상을 치유하지 못해 결국 미쳐 버리고 말았던 걸세.$B$B지금은 고통 속에서 평원을 떠돌며 하루빨리 고통이 끝나기만 기다리고 있지. 나에게', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(538, '안녕하십니까. 당신을 심오한 마법의 세계의 좀 더 깊은 곳으로 안내해 드리겠습니다.', '안녕하십니까. 당신을 심오한 마법의 세계의 좀 더 깊은 곳으로 안내해 드리겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(539, '반갑습니다, $c님. 제가 조언 하나만 하지요. 세상을 여행할 때 부디 마법을 조심하시기 바랍니다. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까요.', '반갑습니다, $c님. 제가 조언 하나만 하지요. 세상을 여행할 때 부디 마법을 조심하시기 바랍니다. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(558, '오, 반가워요. 전 노움 상급 마법사로 여러 가지 마법을 가르치고 있답니다.', '오, 반가워요. 전 노움 상급 마법사로 여러 가지 마법을 가르치고 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(559, '반갑네, $c. 내가 조언 하나만 하지. 세상을 여행할 때 부디 마법을 조심하게. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까.', '반갑네, $c. 내가 조언 하나만 하지. 세상을 여행할 때 부디 마법을 조심하게. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(560, '오, 반가워요. 전 노움 상급 마법사로 여러 가지 마법을 가르치고 있답니다.', '오, 반가워요. 전 노움 상급 마법사로 여러 가지 마법을 가르치고 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(561, '진짜 반가워요. 제가 충고 하나 해 드릴까요? 마법사 하나쯤은 친구로 사귀어 두라고요! 우린 상당히 재주가 좋거든요! 아, 정말이라니까요...', '진짜 반가워요. 제가 충고 하나 해 드릴까요? 마법사 하나쯤은 친구로 사귀어 두라고요! 우린 상당히 재주가 좋거든요! 아, 정말이라니까요...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(562, '반갑네. 나는 상급 마법사로 여러 가지 마법을 가르치고 있다네.', '반갑네. 나는 상급 마법사로 여러 가지 마법을 가르치고 있다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(563, '반갑습니다, $c님. 제가 조언 하나만 하지요. 세상을 여행할 때 부디 마법을 조심하시기 바랍니다. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까요.', '반갑습니다, $c님. 제가 조언 하나만 하지요. 세상을 여행할 때 부디 마법을 조심하시기 바랍니다. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(564, '반갑습니다. 알려지지 않은 마법을 배우러 오셨습니까?', '반갑습니다. 알려지지 않은 마법을 배우러 오셨나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(565, '안녕하신가, $c|1이여;여;. 안타깝지만 자네에게 진정한 마법의 비밀을 가르쳐 줄 수 없는 것이 유감이네...', '안녕하신가, $c|1이여;여;. 안타깝지만 자네에게 진정한 마법의 비밀을 가르쳐 줄 수 없는 것이 유감이네...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(580, '당신은 아직 여기 올 때가 아닙니다. 다시 삶의 세계로 돌아갈 수 있도록 내가 도와드리겠습니다... 하지만 약간의 대가를 치러야 합니다.', '당신은 아직 여기 올 때가 아닙니다. 다시 삶의 세계로 돌아갈 수 있도록 내가 도와드리겠습니다... 하지만 약간의 대가를 치러야 합니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(581, '실바나스 여군주님의 재가로 죽음추적자의 수가 늘어나고 있소. 이제 적이 눈치채지 못할 때 더욱 치명적인 공격을 감행할 수 있을 거야.', '실바나스 여군주님의 재가로 죽음추적자의 수가 늘어나고 있소. 이제 적이 눈치채지 못할 때 더욱 치명적인 공격을 감행할 수 있을 거야.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(623, '원하는 게 뭐요, $c? 난 너무 늦었다고. 내 고용주는 일 처리를 굼뜨게 하는 걸 절대 달가워하지 않을 거란 말이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(624, '그런데, 무슨 일이오?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(638, '으스러진 손은 영광스러웠던 호드의 시대를 열 것이다.', '으스러진 손은 영광스러웠던 호드의 시대를 열 것이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(678, '당신 같은 젊은 $c|1이;가; 이 늙은 농부에겐 무슨 일로 오셨소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(698, '나랄렉스 님께서 또 잠이 드셨소!$B$B아주 오래전, 나랄렉스 님께서는 에메랄드의 꿈속으로 들어가 불모의 땅을 울창한 숲으로 만들겠다는 고귀한 뜻을 품고 이 동굴로 먼 길을 오셨소. 하지만 나랄렉스 님의 집중력이 약해지면서 뱀의 형상이 에메랄드의 꿈을 더럽히게 되었소.$B$B나랄렉스 님을 괴롭히는 그 파충류들이 이제는 이 땅까지 스며나오고 있소. 나랄렉스 님께서 악몽에서 깨어나지 않으면, 영원히 그분을 잃게 될 거요. 그러면 엄청난 악의 힘이 풀려나게', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(699, '송곳니 군주들이 죽었소! 아직 희망이 모두 사라진 건 아니오! 하지만 자각의 의식은 꽤 복잡하여 혼자서는 할 수 없소.$B$B필요한 준비는 내가 모두 할 테니 당신은 나를 지켜주어야 하오. 에메랄드의 꿈을 통해 나랄렉스 님의 여행에서 소환된 몽마들은 상당히 위협적이오. 당신이 도와주지 않는다면 이 임무는 실패할 거요.$B$B나를 지켜줄 줄 준비가 되거든 말해주시오. 그러면 나랄렉스 님의 안식처로 안내하겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(718, '기계가 이쪽을 돌아봅니다.$B$B기계 뒷면에는 이상한 형태로 뒤틀린 홈이 있고 ''겔카크 자이로마스트 선장의 물건''이라는 글귀가 새겨져 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(720, '이보시오! 틸스의 심부름을 온 거요? 내가 당신이라면 그자를 가까이하지 않을 거요. 술에 절어 제정신이 아니지... 하지만 마법만은 여전히 강력하다오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(738, '좋소. 말해 주겠소. 대신 나를 틸스에게 데려가지 않는다면 말이오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(758, '겔카크의 열쇠를 빈 홈에 넣으니 꼭 들어맞습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(759, '철 족쇄에 묶여 꼼짝도 못하는 나를 조롱하는 것인가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(760, '인간 중 한 명에게 이 고약한 장치의 열쇠가 있소. 여기 있는 자들이 그를 에스턴이라고 부르는 것 같더군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(761, '여기서 나가시오, $c 친구. 아니면 저들이 당신을 족쇄로 묶어버릴 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(762, '말겐... 교도관 중에 한 명이지. 그 녀석에게 내 족쇄 열쇠가 있소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(764, '은행은 성문의 북서쪽 상업 지구에 있습니다. 지도를 통해 위치를 알려드리겠습니다.', '은행은 성문의 북서쪽 상업 지구에 있습니다. 지도를 통해 위치를 알려드리겠습니다.', '스톰윈드 회계사무소는 스톰윈드 상업 지구의 성문 옆에 있습니다. 돈을 세는 게 지겨워질 때는 꼭 황금 장미 여관에 들러 한잔 하시기 바랍니다.', '스톰윈드 회계사무소는 스톰윈드 상업 지구의 성문 옆에 있습니다. 돈을 세는 게 지겨워질 때는 꼭 황금 장미 여관에 들러 한잔 하시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(766, '던 모로에 쌓인 눈이 모두 녹아 없어져 버렸으면 좋겠다오. 항상 내 로브 자락을 적실뿐더러 모든 걸 지저분하게 만든단 말이지!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(767, '아이고, 지겨운 눈 같으니... 거기, 당신 $n 아니신가? 당신에게 전할 말이 있다오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(768, '아이언포지의 최고 흑마법사이신 라고 블랙렌치께서 당신을 찾고 계시오. 즉시 그분께 가서 보고를 드리는 게 좋겠소. 아이언포지의 쓸쓸한 뒷골목에 가면 그분을 만날 수 있을 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(769, '$C|1이여;여;, 만나서 반갑소. 나는 타나리운 트리텐더라 하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(778, '앞으로 경주를 어떻게 예상하느냐고요? 물론 우리 고블린이 한 발 앞서 있죠. 멋진 도구와 뛰어난 재능이 있으니까요!', '앞으로 경주를 어떻게 예상하느냐고요? 물론 우리 고블린이 한 발 앞서 있죠. 멋진 도구와 뛰어난 재능이 있으니까요!', '노움들의 그 빌어먹을 행운만 아니라면 절대 우리를 이기지 못할 거예요!', '노움들의 그 빌어먹을 행운만 아니라면 절대 우리를 이기지 못할 거예요!', '나라면 고블린 상품 교환권을 사겠어요. 다른 팀에 거는 건 생돈 날리는 일이라고요.', '나라면 고블린 상품 교환권을 사겠어요. 다른 팀에 거는 건 생돈 날리는 일이라고요.', '난 우리 고블린이 이긴다에 전 재산을 걸겠어요! 당신도 생각이 있다면 나처럼 하겠지요?', '난 우리 고블린이 이긴다에 전 재산을 걸겠어요! 당신도 생각이 있다면 나처럼 하겠지요?', '다음 경주에서는 노움의 차를 날려버릴 거라고 그러더군요! 농담이든 진담이든 간에 나 같으면 멀찌감치 떨어져 있을 거예요.', '다음 경주에서는 노움의 차를 날려버릴 거라고 그러더군요! 농담이든 진담이든 간에 나 같으면 멀찌감치 떨어져 있을 거예요.', NULL, NULL, NULL, NULL, NULL, NULL),
(779, '아, 존슨 말입니까? 어딘가 숨어있다고 들었는데...', '아, 존슨 말입니까? 어딘가 숨어있다고 들었는데...', '며칠째 틸스가 존슨을 찾고 있는데 도무지 모습을 드러내지 않고 있지요. 바로 저기 저 닭이에요!', '며칠째 틸스가 존슨을 찾고 있는데 도무지 모습을 드러내지 않고 있지요. 바로 저기 저 닭이에요!', '씩씩이 그 친구를 찾는 거요? 탑 위에 있는 크론크라이더에게 물어보면 말해줄 거요. 내가 가르쳐줬다고는 아무한테도 말하지 말고...', '씩씩이 그 친구를 찾는 거요? 탑 위에 있는 크론크라이더에게 물어보면 말해줄 거요. 내가 가르쳐줬다고는 아무한테도 말하지 말고...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(780, '고블린 녀석들의 그 믿을 수 없는 행운만 아니었으면 경주 때마다 차가 완전히 박살났을 텐데!', '고블린 녀석들의 그 믿을 수 없는 행운만 아니었으면 경주 때마다 차가 완전히 박살났을 텐데!', '이 경주는 우리 노움의 뛰어난 창의력을 만천하에 보여줄 좋은 기회야!', '이 경주는 우리 노움의 뛰어난 창의력을 만천하에 보여줄 좋은 기회야!', '우리 경주차의 행렬 열도계에 새로운 장치를 설치했소. 마하 15는 거뜬히 나올 거요!', '우리 경주차의 행렬 열도계에 새로운 장치를 설치했소. 마하 15는 거뜬히 나올 거요!', '내 세 살배기 아들 녀석도 저 투박하고 엉성한 고블린 경주차보다는 더 빠른 차를 만들 수 있을 거요!', '내 세 살배기 아들 녀석도 저 투박하고 엉성한 고블린 경주차보다는 더 빠른 차를 만들 수 있을 거요!', '내 태엽 점성장치에 의하면 지난 시합 때보다 20초는 더 빨리 고블린을 이길 수 있을 것 같소!', '내 태엽 점성장치에 의하면 지난 시합 때보다 20초는 더 빨리 고블린을 이길 수 있을 것 같소!', NULL, NULL, NULL, NULL, NULL, NULL),
(781, '틸스가 요즘 제정신이 아니라더니 그 조수도 마찬가지군.', '틸스가 요즘 제정신이 아니라더니 그 조수도 마찬가지군.', '존슨? 이 근처 어딘가에 있을 텐데...', '존슨? 이 근처 어딘가에 있을 텐데...', '씩씩이 말이오? 탑 위에 있는 경주진행자 크롱크라이더가 그가 있는 곳을 안다고 하더군.', '씩씩이 말이오? 탑 위에 있는 경주진행자 크롱크라이더가 그가 있는 곳을 안다고 하더군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(798, '드디어 이 감옥에서 해방이 됐군!$B$B나는 이곳 은빛소나무 숲에서 아루갈이 언데드를 어떻게 상대하고 있는지 조사하라는 키린 토의 지시를 받고 달라란에서 왔습니다. 아루갈이 미쳐버린 줄은 아무도 몰랐지요.$B$B즉시 이 사태에 대해 보고를 해야 합니다! 하지만 떠나기 전에 안마당 문에 걸린 마법 자물쇠를 풀어 드리지요.$B$B당신은 레실고어를 물리쳤으니 아마 이 문 너머 세상에서도 살아남을 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(799, '드디어! 저를 이 감옥에서 구해줄 분이 오셨군요! 오, 여왕이시여! 감사합니다!$B$B우리는 아루갈을 일망타진할 계획을 세울 수 있도록 성채에 관한 정보를 모아오라는 고위집행관 하드렉의 지시를 받고 왔습니다.$B$B하지만 그 늙은 마법사가 많은 계략을 숨겨놓는 바람에 우리는 마법 감시망에 걸려 들켜버리고 말았지요. 저는 살아남아 이 감옥에라도 갇혔지만 빈센트는 운이 좋지 않았습니다.$B$B즉시 하드렉에게 돌아가 이 일을 보고해야 합니다. 그 전에 먼저', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(818, '나는 한때 황혼의 망치단을 따랐었소. 고대 신들을 환생시키는 데 집착했던 나는 그 몹쓸 짐승 아쿠마이의 힘을 얻기 위해 이 깊은 굴속으로 들어왔지.$B$B수많은 무고한 생명이 제물로 바쳐지는 것을 보고서야 정신을 차리게 되었소.$B$B이제는 덫에서 풀려나 자유의 몸이 되었소! 하지만 고향인 카즈 모단은 너무나 멀리 있군.$B$B용감한 모험가여, 아쿠마이를 처치해 준 답례로 아주 특별한 땅으로 가는 길을 알려주겠소. 원한다면 다르나서스로 이동시켜주리다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(820, '여행으로 지치신 분이시여, 저희 여관에 오신 것을 환영합니다! 무엇을 도와 드릴까요?', '여행으로 지치신 분이시여, 저희 여관에 오신 것을 환영합니다! 무엇을 도와 드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(821, '여관에서 푹 쉬시면서 지친 몸을 달래시기 바랍니다.', '여관에서 푹 쉬시면서 지친 몸을 달래시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(822, '저희 여관을 찾아주시는 분은 초원에서 불어오는 시원한 바람처럼 언제나 대환영이랍니다.', '저희 여관을 찾아주시는 분은 초원에서 불어오는 시원한 바람처럼 언제나 대환영이랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(823, '손님, 맥주잔을 가득 채워드리겠습니다. 의자를 당겨 편히 앉으세요. 저희 여관에는 언제나 술이 찰랑거리는 맥주통과 정다운 이야기들이 있답니다.', '손님, 맥주잔을 가득 채워드리겠습니다. 의자를 당겨 편히 앉으세요. 저희 여관에는 언제나 술이 찰랑거리는 맥주통과 정다운 이야기들이 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(824, '손님의 얼굴과 영혼은 지치고 힘들어 보이는군요. 저희 여관에서 지친 몸을 편히 뉘이시고 꿈속에서 엘룬께 조언을 구하시기 바랍니다.', '손님의 얼굴과 영혼은 지치고 힘들어 보이는군요. 저희 여관에서 지친 몸을 편히 뉘이시고 꿈속에서 엘룬께 조언을 구하시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(825, '자, 자, 어서 들어오세요. 난로에는 너무 가까이 앉지 않는 게 좋습니다요, 손님. 오늘은 아직 불이 나지 않았지만 제 생각엔 다른 곳에 앉으시는 게 안전할 거 같습니다.', '자, 자, 어서 들어오세요. 난로에는 너무 가까이 앉지 않는 게 좋습니다요, 손님. 오늘은 아직 불이 나지 않았지만 제 생각엔 다른 곳에 앉으시는 게 안전할 거 같습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(838, '$r|1이여;여;. 만나서 반갑습니다.', '$r|1이여;여;. 만나서 반갑습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(878, '자... 고양이가 뭘 가져왔는지 볼까? ... 아, 뭘 도와드릴까요?', '자... 고양이가 뭘 가져왔는지 볼까? ... 아, 뭘 도와드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(879, '오, 여행을 떠나시려는가 보군요. 영웅의 계곡이 내려다보이는 북동쪽 성벽에 가시면 그리핀 조련사를 만나실 수 있습니다.', '오, 여행을 떠나시려는가 보군요. 영웅의 계곡이 내려다보이는 북동쪽 성벽에 가시면 그리핀 조련사를 만나실 수 있습니다.', '아하, 덩가 롱드링크 씨를 찾고 계시군요. 그는 카즈 모단에선 제일 빠른 그리핀을 부리고 있답니다! 그를 만나려면 상업 지구에서 계단을 따라 성벽으로 올라가면 됩니다.', '아하, 덩가 롱드링크 씨를 찾고 계시군요. 그는 카즈 모단에선 제일 빠른 그리핀을 부리고 있답니다! 그를 만나려면 상업 지구에서 계단을 따라 성벽으로 올라가면 됩니다.', '그리핀 탑승장을 찾으시는군요? 덩가 씨는 상업 지구에 성벽 위에서 자신의 그리핀을 지키고 있습니다. 그리핀에 탑승하시면 꼭 붙잡고 계셔야 한다는 거 잊지 마시기 바랍니다!', '그리핀 탑승장을 찾으시는군요? 덩가 씨는 상업 지구에 성벽 위에서 자신의 그리핀을 지키고 있습니다. 그리핀에 탑승하시면 꼭 붙잡고 계셔야 한다는 거 잊지 마시기 바랍니다!', '오, 여행을 떠나시려는가 보군요. 영웅의 계곡이 내려다보이는 북동쪽 성벽에 가시면 그리핀 조련사를 만나실 수 있습니다.', '오, 여행을 떠나시려는가 보군요. 영웅의 계곡이 내려다보이는 북동쪽 성벽에 가시면 그리핀 조련사를 만나실 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(882, '상업 지구에 있는 스톰윈드 사무소로 가서 앨드윈 래프린을 만나보십시오.', '상업 지구에 있는 스톰윈드 사무소로 가서 앨드윈 래프린을 만나보십시오.', '상업 지구에 있는 스톰윈드 사무소로 가서 앨드윈 래프린을 만나보십시오.', '상업 지구에 있는 스톰윈드 사무소로 가서 앨드윈 래프린을 만나보십시오.', '아, 스톰윈드 사무소를 찾으시는군요. 영웅의 계곡에서 성문을 지나 바로 왼쪽에 있는 첫 번째 건물입니다. 그리로 가보십시오.', '아, 스톰윈드 사무소를 찾으시는군요. 영웅의 계곡에서 성문을 지나 바로 왼쪽에 있는 첫 번째 건물입니다. 그리로 가보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(898, '어떤 직업 상급자를 찾으십니까?', '어떤 직업 상급자를 찾으십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(899, '마법사 지구에 있는 마법사의 성소로 가면 스톰윈드의 저명한 마법사들이 모여 있습니다. 그 멋진 곳과 비하면 우리 경비병 거처는 완전히 돼지 우리나 다름없어요.', '마법사 지구에 있는 마법사의 성소로 가면 스톰윈드의 저명한 마법사들이 모여 있습니다. 그 멋진 곳과 비하면 우리 경비병 거처는 완전히 돼지 우리나 다름없어요.', '아, 신비로운 주문을 배우고 싶습니까? 그렇다면, 마법사 지구에 있는 마법사의 성소보다 적당한 곳은 없으니, 그곳을 방문해 보십시오.', '아, 신비로운 주문을 배우고 싶습니까? 그렇다면, 마법사 지구에 있는 마법사의 성소보다 적당한 곳은 없으니, 그곳을 방문해 보십시오.', '듣자하니 마지노르 뒤마를 만나고 싶어하시는 것 같군요! 그분은 항상 마법사 지구에 있는 마법사의 성소에 계십니다. 그 마법사들이 언제 어디로 차원문을 통해 사라져 버릴지 아무도 모른답니다.', '듣자하니 마지노르 뒤마를 만나고 싶어하시는 것 같군요! 그분은 항상 마법사 지구에 있는 마법사의 성소에 계십니다. 그 마법사들이 언제 어디로 차원문을 통해 사라져 버릴지 아무도 모른답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(900, '그렇다면, 밤의 사나이 오스본을 만나 보셔야겠습니다. 스톰윈드에서 그보다 더 은신에 능숙한 선생은 없답니다. 구 시가지에 가시면 그를 만날 수 있을 겁니다.', '그렇다면, 밤의 사나이 오스본을 만나 보셔야겠습니다. 스톰윈드에서 그보다 더 은신에 능숙한 선생은 없답니다. 구 시가지에 가시면 그를 만날 수 있을 겁니다.', '흠, 이곳 스톰윈드에서 도적들은 순전히 우리 애만 먹이고 있다고요. 지금이라도 할 수만 있다면 구 시가지에서 오스본과 마티아스를 끌어다가 지하감옥에 잡아넣고 싶답니다.', '흠, 이곳 스톰윈드에서 도적들은 순전히 우리 애만 먹이고 있다고요. 지금이라도 할 수만 있다면 구 시가지에서 오스본과 마티아스를 끌어다가 지하감옥에 잡아넣고 싶답니다.', '그렇다면, 밤의 사나이 오스본을 만나 보셔야겠습니다. 스톰윈드에서 그보다 더 은신에 능숙한 선생은 없답니다. 구 시가지에 가시면 그를 만날 수 있을 겁니다.', '그렇다면, 밤의 사나이 오스본을 만나 보셔야겠습니다. 스톰윈드에서 그보다 더 은신에 능숙한 선생은 없답니다. 구 시가지에 가시면 그를 만날 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(901, '구 시가지의 스톰윈드 병영이나 돼지와 휘파람 선술집에 강인한 전사들이 모여 있습니다. 모르긴 몰라도 지금쯤 선술집에 모여서 왁자지껄 술잔을 기울이며 시간을 보내고 있을 테니 그리로 한번 가보십시오.', '구 시가지의 스톰윈드 병영이나 돼지와 휘파람 선술집에 강인한 전사들이 모여 있습니다. 모르긴 몰라도 지금쯤 선술집에 모여서 왁자지껄 술잔을 기울이며 시간을 보내고 있을 테니 그리로 한번 가보십시오.', '전사 훈련을 받으려고 하십니까? 시간만 있다면 제가 누구보다 잘 가르쳐 드릴 자신이 있습니다만, 경비병의 직무 때문에 그럴 수는 없겠군요. 구 시가지에 있는 돼지와 휘파람 선술집이나 스톰윈드 병영 근처에서 상급 전사분을 찾아보시는 게 좋겠습니다.', '전사 훈련을 받으려고 하십니까? 시간만 있다면 제가 누구보다 잘 가르쳐 드릴 자신이 있습니다만, 경비병의 직무 때문에 그럴 수는 없겠군요. 구 시가지에 있는 돼지와 휘파람 선술집이나 스톰윈드 병영 근처에서 상급 전사분을 찾아보시는 게 좋겠습니다.', '구 시가지에서 돼지와 휘파람 선술집이나 스톰윈드 병영을 찾아보시기 바랍니다. 아, 선술집에 들르시면 꼭 그곳 맥주를 맛보십시오. 드워프가 만든 맥주와는 비교도 안 될 겁니다.', '구 시가지에서 돼지와 휘파람 선술집이나 스톰윈드 병영을 찾아보시기 바랍니다. 아, 선술집에 들르시면 꼭 그곳 맥주를 맛보십시오. 드워프가 만든 맥주와는 비교도 안 될 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(902, '스톰윈드의 파괴된 공원과 더불어 그 안에 있던 애처롭고 운이 없었던 영혼들인 나이트 엘프 대부분을 찾는 거라면... 가장 좋은 방법은 드워프 지구 바로 밖에 있는 옛 셀레스틴을 찾는 걸 겁니다.$B$B북쪽 단에서부터 아래로 이어지는 계단이 있습니다. 그곳에서 그녀의 작은 집을 볼 수 있습니다.', '스톰윈드 공원에 가시면 달샘 근처에서 맬드린이나 세리단을 만날 수 있습니다. 공원은 마법사 지구와 대성당 광장의 사이, 스톰윈드의 서쪽 구역에 있습니다.', '상급 드루이드를 찾으려면 스톰윈드 공원으로 가셔야 합니다. 공원 중앙에 있는 달샘에 가면 맬드린과 세리단을 만나실 수 있습니다.', '상급 드루이드를 찾으려면 스톰윈드 공원으로 가셔야 합니다. 공원 중앙에 있는 달샘에 가면 맬드린과 세리단을 만나실 수 있습니다.', '자연의 길을 배우고 싶으시다면 스톰윈드 공원의 달샘 부근으로 가보시기 바랍니다.', '자연의 길을 배우고 싶으시다면 스톰윈드 공원의 달샘 부근으로 가보시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(903, '대성당 광장에 있는 빛의 대성당은 스톰윈드 사제들에게 안식처와 같은 곳이랍니다. 그곳에서 대여사제 로레나 님을 만나보도록 하십시오.', '대성당 광장에 있는 빛의 대성당은 스톰윈드 사제들에게 안식처와 같은 곳이랍니다. 그곳에서 대여사제 로레나 님을 만나보도록 하십시오.', '스톰윈드의 대여사제 로레나 님을 만나보시기 바랍니다. 대성당 광장의 빛의 대성당으로 가시면 그분을 뵐 수 있습니다.', '스톰윈드의 대여사제 로레나 님을 만나보시기 바랍니다. 대성당 광장의 빛의 대성당으로 가시면 그분을 뵐 수 있습니다.', '대성당 광장에 있는 빛의 대성당으로 가서 상급 사제들을 만나보시는 게 좋겠습니다.', '대성당 광장에 있는 빛의 대성당으로 가서 상급 사제들을 만나보시는 게 좋겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(904, '강인한 성기사가 되기 위한 가르침을 받으려면 그레이슨 섀도브레이커 경만한 스승도 없을 겁니다. 그분은 대성당 광장에 있는 빛의 대성당에서 만나실 수 있습니다.', '강인한 성기사가 되기 위한 가르침을 받으려면 그레이슨 섀도브레이커 경만한 스승도 없을 겁니다. 그분은 대성당 광장에 있는 빛의 대성당에서 만나실 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(905, '톨핀 스톤쉴드가 아이언포지에서 이곳까지 와서 사냥을 가르치고 있습니다. 드워프 지구를 가득 채우고 있는 자욱한 연기 속을 헤치고 나갈 자신이 있으신가요? 드워프 지구 북동쪽에 있는 그의 집으로 찾아가보십시오.', '톨핀 스톤쉴드가 아이언포지에서 이곳까지 와서 사냥을 가르치고 있습니다. 드워프 지구를 가득 채우고 있는 자욱한 연기 속을 헤치고 나갈 자신이 있으신가요? 드워프 지구 북동쪽에 있는 그의 집으로 찾아가보십시오.', '톨핀 스톤쉴드가 아이언포지에서 이곳까지 와서 사냥을 가르치고 있습니다. 드워프 지구를 가득 채우고 있는 자욱한 연기 속을 헤치고 나갈 자신이 있으신가요? 드워프 지구 북동쪽에 있는 그의 집으로 찾아가보십시오.', '톨핀 스톤쉴드가 아이언포지에서 이곳까지 와서 사냥을 가르치고 있습니다. 드워프 지구를 가득 채우고 있는 자욱한 연기 속을 헤치고 나갈 자신이 있으신가요? 드워프 지구 북동쪽에 있는 그의 집으로 찾아가보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(906, '뭐라고 하셨습니까? 스톰윈드에 흑마법사가 있다고요? 제가 스톰윈드에서 경비 업무를 시작한 이후 상급 흑마법사가 있다는 소리는 처음 들어봅니다만...nn마법사 지구에 있는 어둠의 희생양 선술집에서 악마를 소환해 부리는 광경을 목격했다는 소리를 들어는 보았습니다. 그곳을 한번 찾아보시는 게 어떨까 싶습니다.', '뭐라고 하셨습니까? 스톰윈드에 흑마법사가 있다고요? 제가 스톰윈드에서 경비 업무를 시작한 이후 상급 흑마법사가 있다는 소리는 처음 들어봅니다만...\n마법사 지구에 있는 어둠의 희생양 선술집에서 악마를 소환해 부리는 광경을 목격했다는 소리를 들어는 보았습니다. 그곳을 한번 찾아보시는 게 어떨까 싶습니다.', '흑마법사라고요? 글쎄... 소문에 듣기로는 마법사 지구에 있는 어둠의 희생양이라는 선술집에 그런 족속이 모인다고 합니다. 제가 이런 얘기를 해드린 것은 비밀로 해주십시오.', '흑마법사라고요? 글쎄... 소문에 듣기로는 마법사 지구에 있는 어둠의 희생양이라는 선술집에 그런 족속이 모인다고 합니다. 제가 이런 얘기를 해드린 것은 비밀로 해주십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(907, '어쩌다 이곳까지 오게 되셨소, $n?', '어쩌다 이곳까지 오게 되셨소, $n?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(908, '그 녀석은 날이 갈수록 살이 찌고 타락해지고 있네. 몸에서는 악취도 나지. 더러운 녀석이야. 씻지 않아서 더럽다는 의미만은 아닐세.$B$B험담은 이제 그만하고. 무슨 일로 날 찾아왔는가, $c|1이여;여;?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(918, '어떤 전문 기술을 배우려고 하십니까?', '어떤 전문 기술을 배우려고 하십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(919, '스톰윈드에서 연금술을 배워보려고 하신다면 연금술 소품점을 권해드리고 싶군요. 마법사 지구에 들어서서 왼쪽 길을 따라 가시면 연금술 소품이라고 쓰인 간판이 걸린 상점을 찾으실 수 있을 겁니다.', '스톰윈드에서 연금술을 배워보려고 하신다면 연금술 소품점을 권해드리고 싶군요. 마법사 지구에 들어서서 왼쪽 길을 따라 가시면 연금술 소품이라고 쓰인 간판이 걸린 상점을 찾으실 수 있을 겁니다.', '마법사 지구에 연금술의 모든 것이라는 작은 상점이 있습니다. 마법사 지구를 지나가다 보면 온갖 기이한 상점들을 보게 되는데, 바깥쪽으로 붙어서 계속 가다 보면 틀림없이 찾을 수 있을 겁니다.', '마법사 지구에 연금술의 모든 것이라는 작은 상점이 있습니다. 마법사 지구를 지나가다 보면 온갖 기이한 상점들을 보게 되는데, 바깥쪽으로 붙어서 계속 가다 보면 틀림없이 찾을 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(920, '테룸 딥포지라는 드워프를 찾아가보십시오. 제가 아는 한 최고의 대장장이입니다. 드워프 지구 중앙에서 만나실 수 있을 겁니다.', '테룸 딥포지라는 드워프를 찾아가보십시오. 제가 아는 한 최고의 대장장이입니다. 드워프 지구 중앙에서 만나실 수 있을 겁니다.', '드워프 가열로의 그윽한 연기 냄새가 나지 않으세요? 대장기술을 배우고 싶으시다면 테룸 딥포지를 찾아가셔야 해요. 대성당 광장 바로 북쪽에 있는 드워프 지구에 있습니다.', '드워프 가열로의 그윽한 연기 냄새가 나지 않으세요? 대장기술을 배우고 싶으시다면 테룸 딥포지를 찾아가셔야 해요. 대성당 광장 바로 북쪽에 있는 드워프 지구에 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(921, '요리의 달인이 되고 싶으신가요? 구 시가지에 있는 돼지와 휘파람 선술집에 가셔서 스티븐 라이백을 만나보시기 바랍니다. 그 친구 갈비 요리는 누구도 따라올 수가 없답니다.nn이런, 갑자기 그가 만든 특제 돼지 갈비가 먹고 싶어 지는군요! 그 비법을 전수해 줄 거라곤 기대하지 마십시오!', '요리의 달인이 되고 싶으신가요? 구 시가지에 있는 돼지와 휘파람 선술집에 가셔서 스티븐 라이백을 만나보시기 바랍니다. 그 친구 갈비 요리는 누구도 따라올 수가 없답니다.\n이런, 갑자기 그가 만든 특제 돼지 갈비가 먹고 싶어 지는군요! 그 비법을 전수해 줄 거라곤 기대하지 마십시오!', '구 시가지, 돼지와 휘파람 선술집에 훌륭한 요리사가 일하고 있습니다. 우리끼리니까 하는 얘기지만, 요리할 때 칼 놀리는 솜씨를 보아하니 전에 요리사 말고 다른... 일도 했을 것 같더군요. 뭐, 이상한 상상은 하지 마시고... 요리를 배우고 싶으시다면 여기서는 그가 최고니까 찾아가 보십시오.', '구 시가지, 돼지와 휘파람 선술집에 훌륭한 요리사가 일하고 있습니다. 우리끼리니까 하는 얘기지만, 요리할 때 칼 놀리는 솜씨를 보아하니 전에 요리사 말고 다른... 일도 했을 것 같더군요. 뭐, 이상한 상상은 하지 마시고... 요리를 배우고 싶으시다면 여기서는 그가 최고니까 찾아가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(922, '스톰윈드에 릴리암 스파크스핀들이라는 영리한 노움 기술자가 체류하고 있습니다. 드워프 지구의 안쪽으로 가면 만날 수 있을 겁니다.', '스톰윈드에 릴리암 스파크스핀들이라는 영리한 노움 기술자가 체류하고 있습니다. 드워프 지구의 안쪽으로 가면 만날 수 있을 겁니다.', '스톰윈드에 릴리암 스파크스핀들이라는 영리한 노움 기술자가 체류하고 있습니다. 드워프 지구의 안쪽으로 가면 만날 수 있을 겁니다.', '스톰윈드에 릴리암 스파크스핀들이라는 영리한 노움 기술자가 체류하고 있습니다. 드워프 지구의 안쪽으로 가면 만날 수 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(923, '스톰윈드에서 모든 구호 활동의 중심지는 빛의 대성당입니다. 그곳에 있는 엔젤라 라이펠트가 응급치료를 익히는 데 도움을 줄 겁니다.', '스톰윈드에서 모든 구호 활동의 중심지는 빛의 대성당입니다. 그곳에 있는 엔젤라 라이펠트가 응급치료를 익히는 데 도움을 줄 겁니다.', '스톰윈드에서 모든 구호 활동의 중심지는 빛의 대성당입니다. 그곳에 있는 엔젤라 라이펠트가 응급치료를 익히는 데 도움을 줄 겁니다.', '스톰윈드에서 모든 구호 활동의 중심지는 빛의 대성당입니다. 그곳에 있는 엔젤라 라이펠트가 응급치료를 익히는 데 도움을 줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(924, '타니사를 찾아가보시기 바랍니다. 마법사 지구의 연금술의 모든 것이라는 상점 밖에 서 있을 겁니다.', '타니사를 찾아가보시기 바랍니다. 마법사 지구의 연금술의 모든 것이라는 상점 밖에 서 있을 겁니다.', '자연과 교류하는 것만큼 즐거운 일도 없죠... 적어도 나이트 엘프들이 하는 얘기로는 그렇더군요. 저는 꽃이며 나무와 대화하는 데는 그다지 취미가 없습니다만, 타니사라면 틀림없이 도와 줄 수 있을 겁니다. 마법사 지구로 가보십시오. 연금술의 모든 것이라는 상점 바깥에 서 있을 겁니다.', '자연과 교류하는 것만큼 즐거운 일도 없죠... 적어도 나이트 엘프들이 하는 얘기로는 그렇더군요. 저는 꽃이며 나무와 대화하는 데는 그다지 취미가 없습니다만, 타니사라면 틀림없이 도와 줄 수 있을 겁니다. 마법사 지구로 가보십시오. 연금술의 모든 것이라는 상점 바깥에 서 있을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(925, '가죽세공이라면 사이먼 태너가 제대로 가르쳐 줄 겁니다. 구 시가지에 있는 태너의 가죽용품점에 가면 만날 수 있을 겁니다.', '가죽세공이라면 사이먼 태너가 제대로 가르쳐 줄 겁니다. 구 시가지에 있는 태너의 가죽용품점에 가면 만날 수 있을 겁니다.', '가죽 냄새를 좋아하시는군요? 그러면 구 시가지에 있는 사이먼 태너와 얘기해 보셔야 할 것 같네요. 태너의 가죽용품점이라는 가게를 운영하고 있습니다.', '가죽 냄새를 좋아하시는군요? 그러면 구 시가지에 있는 사이먼 태너와 얘기해 보셔야 할 것 같네요. 태너의 가죽용품점이라는 가게를 운영하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(927, '겔만 스톤핸드를 만나보시는 게 좋겠군요. 드워프 지구에서 대성당 광장으로 나가는 통로 부근에 있던 어떤 집 안에 살고 있던 걸로 기억합니다. 정확히는 모르겠습니다. 우선 그쪽에서 이층집을 찾아보시기 바랍니다.', '겔만 스톤핸드를 만나보시는 게 좋겠군요. 드워프 지구에서 대성당 광장으로 나가는 통로 부근에 있던 어떤 집 안에 살고 있던 걸로 기억합니다. 정확히는 모르겠습니다. 우선 그쪽에서 이층집을 찾아보시기 바랍니다.', '아이언포지에서 드워프들이 채광 전문가랍시고 한 명을 보내서는 우리한테 채광이 이렇니 저렇니 하는데, 곡괭이 하나 들고 바위나 때리는 게 뭐 그리 어려운 일이라고 그러는지... 뭐, 그래도 여기 와 있는 이상 그를 찾아가 보는 게 좋겠지요. 겔만이라고 하는데, 드워프 지구에 살고 있습니다.', '아이언포지에서 드워프들이 채광 전문가랍시고 한 명을 보내서는 우리한테 채광이 이렇니 저렇니 하는데, 곡괭이 하나 들고 바위나 때리는 게 뭐 그리 어려운 일이라고 그러는지... 뭐, 그래도 여기 와 있는 이상 그를 찾아가 보는 게 좋겠지요. 겔만이라고 하는데, 드워프 지구에 살고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(928, '무두질을 배우고자 한다면 구 시가지에 있는 태너의 가죽용품점에서 매리스 그랑거를 만나보시기 바랍니다.', '무두질을 배우고자 한다면 구 시가지에 있는 태너의 가죽용품점에서 매리스 그랑거를 만나보시기 바랍니다.', '무두질을 배우고자 한다면 구 시가지에 있는 태너의 가죽용품점에서 매리스 그랑거를 만나보시기 바랍니다.', '무두질을 배우고자 한다면 구 시가지에 있는 태너의 가죽용품점에서 매리스 그랑거를 만나보시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(929, '조르지오 볼레로는 스톰윈드에서 가장 훌륭한 재봉사 중 하나랍니다. 그는 마법사 지구에 있는 던컨의 옷가게에서 근무하고 있으니 그곳으로 가보시기 바랍니다.', '조르지오 볼레로는 스톰윈드에서 가장 훌륭한 재봉사 중 하나랍니다. 그는 마법사 지구에 있는 던컨의 옷가게에서 근무하고 있으니 그곳으로 가보시기 바랍니다.', '재봉사라고요? 여기 오래 있다 보니, 조르지오 볼레로란 자에 대한 얘기를 듣게 되었지요. 벌써 여러 해 동안, 동부 왕국의 유행을 창조해, 선도해 가고 있는 최고의 재봉사입니다. 그에게 재봉술을 배우고 싶다면 마법사 지구 외곽에서 찾아보십시오.', '재봉사라고요? 여기 오래 있다 보니, 조르지오 볼레로란 자에 대한 얘기를 듣게 되었지요. 벌써 여러 해 동안, 동부 왕국의 유행을 창조해, 선도해 가고 있는 최고의 재봉사입니다. 그에게 재봉술을 배우고 싶다면 마법사 지구 외곽에서 찾아보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(930, '씩씩이는 자신이 아직 소금 평원에 있다는 사실을 틸스에게 들키고 싶지 않아서 닭으로 변신했지요.$B$B혹시라도 씩씩이를 찾거든 ''/손짓''을 해보십시오. 모습을 드러낼지도 모릅니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(931, '일을 시작할 준비가 되었으면 좋겠군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(932, '경주에 오신 걸 환영합니다! 계시는 동안 맘껏 즐기시기 바랍니다. 하지만 당신 돈을 한 군데 몽땅 걸지는 마십시오!', '경주에 오신 걸 환영합니다! 계시는 동안 맘껏 즐기시기 바랍니다. 하지만 당신 돈을 한 곳에 몽땅 걸지는 마십시오!', '안녕하십니까, $c|1이여;여;! 소금 평원 경주에 온 걸 환영합니다!', '안녕하십니까, $c|1이여;여;! 소금 평원 경주에 온 걸 환영합니다!', '어느 차가 가장 빠를까요? 경주의 승패를 그 누가 알겠습니까?!', '어느 차가 가장 빠를까요? 경주의 승패를 그 누가 알겠습니까?!', '고블린 경주차가 힘이 좋긴 하지만 노움들도 자동차에 한두 가지 비장의 카드 정도는 숨겨놓았을 겁니다.', '고블린 경주차가 힘이 좋긴 하지만 노움들도 자동차에 한두 가지 비장의 카드 정도는 숨겨놓았을 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(933, '어디로 가고자 하십니까?', '어디로 가고자 하십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(934, '세찬 빗속에 있다가 들어온 고양이처럼 내 마음을 마구 긁어대고 할퀴고... 또 할퀴고... 내가 입은 상처가 더 많은...?$B$B아. 들어오시는 걸 못 봤네요, $n! 뭘 도와 드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(938, '이 세계를 우리 것으로 만들려면 전투로 지친 몸을 쉬게 해줘야 할 곳이 필요하답니다. 불 옆에 도끼를 내려두고 당신의 멋진 무용담을 들려주시기 바랍니다.', '이 세계를 우리 것으로 만들려면 전투로 지친 몸을 쉬게 해줘야 할 곳이 필요하답니다. 불 옆에 도끼를 내려두고 당신의 멋진 무용담을 들려주시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(940, '수정 호수에서 즐기는 낚시만큼 여가시간을 보내는데 좋은 취미도 없답니다. 저도 아놀드 리랜드에게 낚시를 배웠죠. 밤낮 대운하 지역에 있는 부두에서 물때를 보고 있으니 쉽게 찾을 수 있을 겁니다.nn참, 그가 대운하에 괴물이 산다는 얘기를 하더라도 그 말을 믿지는 마세요. 절대...', '수정 호수에서 즐기는 낚시만큼 여가시간을 보내는데 좋은 취미도 없답니다. 저도 아놀드 리랜드에게 낚시를 배웠죠. 밤낮 대운하 지역에 있는 부두에서 물때를 보고 있으니 쉽게 찾을 수 있을 겁니다.\n참, 그가 대운하에 괴물이 산다는 얘기를 하더라도 그 말을 믿지는 마세요. 절대...', '리랜드라는 한량 말이로군요. 그가 하는 일이라고는 상업 지구 외곽에 있는 부두에 죽치고 앉아 하루종일 낚시하는 것뿐이죠. 늘 고기나 낚고 있으니 솜씨는 분명 괜찮을 겁니다. 낚시를 배우고 싶으시다면 그를 찾아가 보시죠.', '리랜드라는 한량 말이로군요. 그가 하는 일이라고는 상업 지구 외곽에 있는 부두에 죽치고 앉아 하루종일 낚시하는 것뿐이죠. 늘 고기나 낚고 있으니 솜씨는 분명 괜찮을 겁니다. 낚시를 배우고 싶으시다면 그를 찾아가 보시죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(941, '루칸 코르델은 스톰윈드 지하감옥 근처 대운하 가장자리에 작은 상점을 하나 운영하고 있습니다. 장담하건대 그라면 마법부여의 경지가 무엇인지 보여줄 겁니다.', '루칸 코르델은 스톰윈드 지하감옥 근처 대운하 가장자리에 작은 상점을 하나 운영하고 있습니다. 장담하건대 그라면 마법부여의 경지가 무엇인지 보여줄 겁니다.', '아, 루칸 코르델을 찾으시는군요. 지하감옥으로 가는 길, 마법 지구 외곽에서 상점을 운영하고 있답니다.', '아, 루칸 코르델을 찾으시는군요. 지하감옥으로 가는 길, 마법 지구 외곽에서 상점을 운영하고 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(942, '나는 이 땅에서 적을 몰아내고 명예를 지키기 위해 고독한 길을 걷고 있지.$B$B$n, 내가 도와줄 일이 있나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(943, '그래, 그대가 찾는 주술사를 본 적 있어. 마지막으로 목격한 게 아마 서쪽에서였지. 보통 서슬갈기 일족의 본거지가 내려다보이는 언덕에 숨어서 지낸다네. 머리를 좀 쓰면 포악한 가시멧돼지 무리와 맞닥뜨리지 않고도, 언덕 위 그녀의 집으로 가는 길을 찾을 수 있을 걸세. 여기서 북쪽으로 그리 멀지 않은 곳에 있으니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1038, '으스러진 손은 스랄이 있기 전부터 존재했고 스랄이 죽은 후에도 존재할 것이다.', '으스러진 손은 스랄이 있기 전부터 존재했고 스랄이 죽은 후에도 존재할 것이다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1039, '으스러진 손의 잔도잔이라고 하오. 나, 잔도잔이 뭘 도와주면 되겠소? 솔직히 이 잔도잔 할까 말까 고민 중이오!', '으스러진 손의 잔도잔이라고 하오. 나, 잔도잔이 뭘 도와주면 되겠소? 솔직히 이 잔도잔 할까 말까 고민 중이오!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1040, '훈련을 받으러 온 것인가? 아니면 여기서 전사의 귀중한 시간을 허비하러 온 것인가?', '훈련을 받으러 온 것인가? 아니면 여기서 전사의 귀중한 시간을 허비하러 온 것인가?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1041, '손을 대자 기계가 살아난 듯이 움직입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1058, '그가 벌꿀술도 갖다 주고$B맥주도 갖다 줄 것이라네.$B입이 귀에 걸리도록 히죽대고 있는 얼굴$B해마다 변함없이 우리를 기쁘게 한다네.$B우리는 그를 유쾌한 짐이라 부른다네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1059, '텔드랏실의 다른 곳에서는 볼 수 없는 아주 특이한 식물입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1060, '이 식물은 신기한 보라색 광채를 내뿜기 때문에 텔드랏실의 다른 식물들보다 눈에 잘 띄고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1079, '안녕하십니까. 저의 역할은 아제로스 세계에 창조주가 행한 토석인 합성에 대한 정보를 이용할 수 있게 해주는 일과 권한이 허용된 분에게 이 정보에 대한 지식을 제공하는 것입니다. 원하면 언제든지 정보를 이용할 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1080, '토석인이란 창조주가 합성한 종족의 하나로서 아제로스 세계의 초기 모태 종족 중 하나였습니다. 창조주는 이 세계의 기반을 만들 때 자신의 수고를 덜기 위하여 토석인을 창조했습니다.$B$B토석인은 창조주가 다른 세계에서 종족을 퍼뜨릴 때 사용한 지하 생물의 모형을 수정한 것입니다. 이들 원형 종족이 최초로 합성된 이후 다양한 변종이 태어났습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1081, '지하 생물 모형이란 창조주께서 이 세계에 종족을 퍼뜨릴 때 사용했던 합성 모형 중 하나입니다. 각각의 합성 모형을 사용해, 창조주는 자신의 목표를 이루었습니다. 아제로스의 경우 지하 생물 모형을 개조하여 내구력이 뛰어나고 지하 건설 작업에 적합한 생물을 창조했습니다. 토석인이 바로 이러한 모형 개조의 결과물입니다.$B$B그런데 이 토석인이 창조주를 위한 작업에 투입된 이후, 극한 환경의 영향으로 인해 그 합성 모형에 예상하지 못한 부작용들이 나타났습니다', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1082, '그 질문에 대답하려면 먼저 토석인에 대한 자세한 설명이 필요할 것 같습니다.$B$B처리 중...$B$B토석인에게 나타난 부작용을 이해하기 위해서는 먼저 토석인의 설계 목적을 이해하는 것이 중요합니다. 토석인은 지하 생물 모형의 생존 능력을 향상시키고자 하는 창조주의 뜻에 따라 설계된 것이며, 아제로스에 함유된 탄력적인 조성 물질을 지하 생물 모형에 더해 만들었습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1083, '탄력적인 조성 물질이란 종족 합성 시 사용되는 기본 성분을 말합니다. 창조주는 토석인을 합성하고자 일반적인 유기 조성 물질 대신 아제로스 지반을 구성하는 물질을 사용했습니다.$B$B창조주는 아제로스의 조성에 대해 연구한 끝에, 아제로스 본질의 탄력적인 전형이 될 수 있는 고급 생명체를 합성할 수 있다는 이론을 세웠습니다. 창조주는 그 이론에 따라 아제로스에 있는 다양한 바위의 핵심 성분을 기초로 하여 더욱 향상된 생명체를 만들었습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1084, '단순하게 말하자면 그렇습니다.$B$B토석인의 신체는 신장이 작은 인간형 생물과 비슷하지만, 토석인을 이루고 있는 것은 아제로스에 있는 여러 가지 바위의 핵심 성분입니다. 토석인은 지적 처리 능력을 크게 떨어뜨리지 않고도 체력을 극대화하는 방식으로 설계되었습니다. 피부와 근육조직은 물리적 손상에 거의 영향을 받지 않으며, 아주 사소한 개조 단계만 거치면 마력에 대해 놀라운 저항 능력을 보입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1085, '이 정보를 완전히 이해하기 위해서는 먼저 알아두어야 할 사실이 있습니다. 창조주는 자신이 떠난 후에도 오랫동안 이 세계의 발전에 중요한 역할을 해줄 종족을 창조하고자 했습니다. 그래서 장기적으로 아제로스 발전에 중요한 존재가 될 종족을 만들었습니다.$B$B참고로 "토석인"이라는 이름은 창조주가 토석인을 만들 때 사용한 구성 물질을 고려하여, 이 종족에게 적절하다고 판단되는 명칭을 직접 붙인 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1086, '토석인 창조 시 나타난 유일한 부작용은 극도로 극한 환경에 처할 경우, 모형이 불안정해지는 경향이 있다는 것입니다.$B$B참고로 새로운 모형을 설계할 때, 지반 건설 작업은 극도로 긴장되는 환경을 복제하는 데 필요한 요구 사항을 충족시키지 못했습니다. 그러므로 초기에 부작용을 예상하지 못한 것은 당연합니다.$B$B불안정화 경향이 발견된 것은 토석인을 본격적으로 투입한 훨씬 다음의 일이었습니다. 창조주는 불안정화 경향이 나타나는 토석인을 모아 다시 합성하', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1087, '[질문을 한 후 꽤 오래 시간이 지난 후...]$B$B현재 요청하신 정보는 본 정보 저장소의 자료에서 찾을 수 없습니다. 원하시는 정보를 제공하지 못한 데 대해 진심으로 사과 드립니다.$B$B본 정보 저장소의 자료 주기가 경신된 후에 요청하십시오. 아제로스에 있는 다른 정보 저장소에서 요청하실 수도 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1088, '토석인의 합성 모형이 불안정해지면 두 가지 결과가 나타날 수 있습니다. 시청각 자료 1번의 설명을 시작합니다...$B$B부작용의 결과, 첫 번째로 변형된 모형은 조합의 퇴행적 산물입니다. 일반적으로 "트로그"라는 명칭으로 불립니다. 이 변형체는 체력이 토석인과 비슷하나 지적 처리 능력은 거의 없는 것으로 판단됩니다. 따라서 트로그의 정신을 움직이는 것은 욕심, 의지, 그리고 교활함 뿐입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1089, '사용자의 연대기적 발언을 본 자료의 기록에 비교하여 실행할 수 없습니다. 죄송합니다.$B$B트로그의 구성 성분 중에도 아제로스의 여러 가지 바위에서 추출한 핵심 성분이 일부 들어 있으나, 지적 처리 능력의 부족으로 인해 이 변형체는 창조주를 만족시키지 못했습니다.$B$B트로그는 표준적인 생물로 번식했습니다. 하지만, 트로그는 기본적으로 다른 트로그를 포함해 바위와 손에 잡을 수 있는 건 무엇이든 먹어 치웁니다. 창조주는 동족을 잡아먹는다는 점을 받아들일', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1090, '시청각 자료 2번의 설명을 시작하겠습니다...$B$B토석인 모형에서 변형된 두 번째 생물은 표준 지하 생물 모형과 비교해 볼 때 바람직한 요소를 많이 지니고 있습니다. 이 변형 생물의 일반 명칭은 "드워프"입니다.$B$B드워프는 토석인 고유의 체력을 지니고 있습니다. 어떤 경우 토석인 모형의 지적 처리 능력을 능가하기도 합니다. 그러나 드워프에게는 아제로스의 여러 가지 바위에서 추출한 핵심 성분이 전혀 없습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1091, '본 정보 저장소에 보관된 자료 내용과 방금 말씀하신 예리한 발언은 분명히 유효한 상관관계가 있습니다.$B$B드워프를 이루는 구성 성분은 아제로스의 돌과 관련이 있습니다. 그러나 극한 환경에 처하면 토석인의 조합 모형 내에서 부작용이 발생해 표준 지하 생물 모형에서 볼 수 있는 기본적인 생물 자원으로 퇴화하게 됩니다.$B$B그러므로 미루어 짐작하고 계셨듯이, 드워프 변형체는 토석인 합성 모형이 퇴화한 결과물입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1092, '사용자의 연대기적 발언을 본 자료의 기록에 비교하여 실행할 수 없습니다. 죄송합니다.$B$B드워프의 정신적인 부분은 아제로스의 돌 구성에 거의 비슷하게 맞추어져 있습니다. 그러나 살아 있는 생물 자원으로 퇴행한 결과, 퇴화한 모형이 주된 부분을 이루고 있습니다. 드워프는 다른 표준 생물에서 흔히 볼 수 있는 방법으로 영양분을 섭취하여 번식합니다.$B$B창조주는 나름대로 가치가 있는 만족스러운 변형체로 드워프를 인식하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1093, '창조주는... 말 그대로 창조주입니다.$B$B창조주는 자신이 계획하고 설계한 그대로 이 세계를 만들고 종족을 퍼뜨렸습니다. 이 세계가 존재하는 근원은 창조주입니다. 물론 다른 수많은 세계가 존재하게 한 장본인이기도 합니다. 즉 아제로스를 창조한 근원인 것입니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1094, '창조주 또한 본 저장소에 보관된 정보가 방대하다는 사실을 인식하고 있습니다. 노르간논의 원반만 맞춘다면 이곳에 저장된 자료의 복사본을 이용하실 수 있습니다.$B$B이제 당신은 본 정보를 이해하기 위한 최소한의 요구 사항은 모두 갖추었습니다. 원하시는 때 노르간논의 원반에 접속해 원반을 조합하기만 하면 됩니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1118, '오, 대장장이가 되고 싶습니까? 저기 있는 장갑과 망치를 집으십시오. 실력이 어떤지 한번 보겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1119, '이렇게 훌륭한 방어구를 본 게 실로 몇 년만인지 모르겠소, $n. 대용광로에서 그룸누스 스틸셰이퍼의 수습 대장장이로 일할 때 이후로는 처음이오. 그라면 분명 방어구 제작에 대해서 당신의 흥미를 끌 만한 기술을 가르쳐줄 수 있을 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1120, '그룸누스를 만나고 싶으면 먼저 아이언포지로 가십시오. 그 도시 한복판으로 가서 대용광로를 둘러보면 그를 찾을 수 있을 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1121, '$n, 당신의 솜씨는 아주 훌륭하군. 인정하긴 싫지만 당신이 만드는 검과 도끼가 내 것보다도 우수한 것은 사실이오. 내가 만난 이들 중에 당신보다 더 기술이 좋은 자는 보르구스 스틸핸드 밖에 없소. 그라면 분명 당신에게 한 수 가르쳐 줄 수 있을 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1122, '보르구스에게 훈련을 받고 싶다고요? 어디 있는지 가르쳐 드리겠어요. 내 대장간에서 북서쪽에 있는 사거리를 지나 서쪽 길로 가십시오. 오른쪽 두 번째 건물에 있을 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1123, '지금 일하느라 바쁜 게 안 보이나? 내 시간을 뺏으려면 그럴듯한 이유를 대야 할 걸세.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1124, '이 땅은 으스러진 손이 지배한다. 우리는 섭정, 치안대, 재판관, 배심원, 그리고 사형 집행자로서 칼림도어를 뒤덮고 있다. 으스러진 손은 모든 것을 볼 수 있고 모든 것을 알고 있다.$B$B당신은 으스러진 손에 봉사하면서 많이 성장했으니 이제 실전 경험을 쌓을 때가 됐다.$B$B다음 임무를 맡을 준비는 되었나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1127, '대용광로에 온 것을 환영하오. 바깥은 추워도 여기는 항상 따뜻하고 편안하지. 망치를 들고 저 모루를 한번 때려보시오. 대용광로의 대장장이가 될만한 소질이 있나 보겠소이다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1128, '모양이 제대로 잡힌 걸 보니, 분명 기능도 괜찮을 거야. 술 내기를 해도 좋아. 브루크의 모퉁이 선술집에서 말이오. $n, 이제 미올로 선더퓨리를 찾아가 보시오. 당신에게 뭔가 가르쳐 줄 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1129, '미올로가 어디 있는지 당연히 가르쳐 드려야죠. 대용광로의 모루 근처에서 일하고 있어요. 그만한 솜씨를 가진 사람도 없으니 미올로의 말을 귀담아 들으세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1130, '아주 맘에 드는 친구로군. 내가 가르친 사람 중에 이렇게 칼을 잘 만드는 사람은 정말 오랜만이오. 하지만 진짜 무기를 만들고 싶거든 미올로 선더퓨리를 찾아가 보시오. 그 드워프라면 당신에게 칼 만드는 법 하나는 제대로 가르쳐줄 수 있을게요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1131, '미올로를 보러 가겠다고? 바로 저기 있소. 당신 뒤에 말이오! 아니... 당신 앞이라고 해야 하나? 어쨌든 거대한 모루 근처에 있소!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1132, '무언가 이 탑에 역병을 퍼뜨리고 있소. 탑 안은 물론이고 근처에서 일하던 다른 투자개발회사 일꾼들도 병에 걸렸소이다. 지난주에만 감시관 둘이 숨졌지. 그런데 글쎄, 죽은 직후 넋 나간 돌연변이로 되살아나지 뭐요!$B$B내 몸에서도 생명력이 빠져나가고 있소. 통제력도 점점 잃어가고. 사악한 충동이 나를 지배... 나쁜 충동이... *피줄이 자신의 따귀를 때립니다* 아직은 안 돼. 잘 들으시오... 나는 이 탑을 감독하는 자요. 이 정도 자리에 있으면 민감', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1133, '정신이 제대로 박힌 건가? 그게 무슨 무기라고 만들고 있나? 배추나 다듬을 수 있겠구먼. 나는 초보자는 가르치지 않네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1135, '고작 이것 때문에 날 성가시게 한 거요? 이 쓰레기를 입고 다니느니 토끼 가죽을 걸치고 트롤의 소굴을 뛰어다니는 것이 낫겠군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1136, '$n|1이라;라; 했소? 아주 강하고 훌륭한 걸 걸치고 있군그래. 훈련을 시켜주지. 마그니 왕께서 몸소 걸칠 만큼 훌륭한 갑옷을 만드는 법을 가르쳐주겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1138, '약 5개월 전, 투자개발회사의 가시덤불 지부에서는 무법항에 있는 크랭크 피즐버브라는 수상한 상인에게 특수한 독을 받기로 계약을 했소. 피즐버브는 잔질에게 독을 훔쳐온 게 분명하오!$B$B그래, 추방자 잔질 말이오. 그 트롤은 강령술 실험을 하곤 했는데, 그 때문에 부족에서 영원히 추방당하고 말았소.$B$B그들은 독을 받은 후 서로 시험해 보기 시작했고 그 결과는 실로 참담했소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1158, '결국, 총감독 푸직 갤리윅스가 끼어들었고 그 나머지 독을 이곳 진흙 늪에 있는 자기 탑으로 가져왔소. 독의 불안정한 성질을 연구하기 위해서라고 둘러대고서 말이지. 그는 데피아즈 결사단에게 그 독의 비밀을 알려주는 대가로, 안정적인 독을 대량 공급받기로 결정했지.$B$B데피아즈 결사단에서는 클라벤 몰트웨이크가 잔질의 혼합물이 지닌 화학적 성질을 바꾸는 일을 맡게 되었소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1159, '중간은 생략하고... 그 결과 얻게 된 제조법은 꽤 효과가 있어서 일꾼들을 좀 더 잘 조종할 수 있게 됐지만, 부작용은 여전히 있었다오. 비활성 혼합물의 휘발성이 너무 높았지...$B$B갤리윅스와 탑 안팎에 있는 자들은 모두 독에 감염되어 버렸소. 그 독은 우리의 신체와 정신에 영향을 미치지. 그 때문에 내부 기관이 극도로 약해져 버렸소. 이게 당신의 기회요, $n. 나는 더는 버틸 기운이 없소. 곧 ''그들''과 한패가 돼버릴 것 같소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1160, '이 탑의 방어력은 매우 약해져 있소. 투자개발회사 순찰대원, 보초, 망꾼은 물론이고 갤리윅스마저 감염되었기 때문에 당신의 공격에 힘없이 무너질 거요.$B$B탑 안으로 들어가시오. 적을 모두 처치하고 나올 때는 잊지 말고 가방에 총감독 푸직 갤리윅스의 머리카락과 남아있는 혼합물을 담아오시오. 그것을 셴툴에게 가져다주시오. 아마도... 그라면 무엇을 해야 할지 알 것이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1202, '이런... 중요한 일을 하던 중이었는데... 날 방해할 만큼 중요한 일이겠지요? 그래, 무슨 일이십니까?', '이런... 중요한 일을 하던 중이었는데... 날 방해할 만큼 중요한 일이겠지요? 그래, 무슨 일이십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1203, '오, 약초채집가로군요. 흠, 보아하니 당신은 아직 잡초나 캐고 있을 것 같으니, 내 제대로 된 약초채집 기술을 몇 가지 가르쳐 주도록 하겠소.', '오, 약초채집가로군요. 흠, 보아하니 당신은 아직 잡초나 캐고 있을 것 같으니, 내 제대로 된 약초채집 기술을 몇 가지 가르쳐 주도록 하겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1205, '여어, 낚시꾼 친구로군. 혹시 훈련이 필요한 게 아니오? 내게 기술을 좀 배워보는 게 어떻겠소?', '여어, 낚시꾼 친구로군. 혹시 훈련이 필요한 게 아니오? 내게 기술을 좀 배워보는 게 어떻겠소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1206, '스톰윈드에 오신 걸 환영합니다. 이 요새를 재건하는 데 오랜 세월이 걸리긴 했지만, 충분히 가치가 있었습니다. 이 장대한 요새에 관광차 온 것입니까? 아니면 따로 볼일이 있어 온 것입니까?', '스톰윈드에 오신 걸 환영합니다. 이 요새를 재건하는 데 오랜 세월이 걸리긴 했지만, 충분히 가치가 있었습니다. 이 장대한 요새에 관광차 온 것입니까? 아니면 따로 볼일이 있어 온 것입니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1207, '요리사 수련을 받으러 이곳까지 날 찾아오는 이들은 드물지만, 당신이 준비가 되었다면 요리의 기본 정도는 가르쳐드릴 수 있을 듯싶습니다.', '요리사 수련을 받으러 이곳까지 날 찾아오는 이들은 드물지만, 당신이 준비가 되었다면 요리의 기본 정도는 가르쳐드릴 수 있을 듯싶습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1208, '이곳을 드나드는 관광객들을 모두 돌봐줄 정도로 제가 시간과 정력이 남아도는 줄 아십니까? 어서 용건만 간단히 말씀해 보십시오.', '이곳을 드나드는 관광객들을 모두 돌봐줄 정도로 제가 시간과 정력이 남아도는 줄 아십니까? 어서 용건만 간단히 말씀해 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1210, '무두질을 배우러 이곳까지 날 찾아오는 일은 드문데... 그래도 당신이 준비가 되었다면 쓸만한 기술은 몇 가지 가르쳐줄 수도 있을 것 같군요.', '무두질을 배우러 이곳까지 날 찾아오는 일은 드문데... 그래도 당신이 준비가 되었다면 쓸만한 기술은 몇 가지 가르쳐줄 수도 있을 것 같군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1215, '큰 전쟁은 끝났을지 모르지만 전사로서 기술 연마를 게을리해서는 안 돼!', '큰 전쟁은 끝났을지 모르지만 전사로서 기술 연마를 게을리해서는 안 돼!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1216, '스톰윈드는 우리 인간 종족의 요지로서, 용감한 우리 전사들의 굳건한 의지와 힘으로 지켜내고 있소.', '스톰윈드는 우리 인간 종족의 요지로서, 용감한 우리 전사들의 굳건한 의지와 힘으로 지켜내고 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1217, '엘룬의 축복을 그대에게... 전투 기술도 잘만 배우면 예술의 경지에 이를 수 있답니다.', '엘룬의 축복을 그대에게... 전투 기술도 잘만 배우면 예술의 경지에 이를 수 있답니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1218, '배움의 길은 끝이 없는 법이지요... 꾸준히 정진해 나가길 바랍니다.', '배움의 길은 끝이 없는 법이지요... 꾸준히 정진해 나가길 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1219, '전사의 역할 중 하나는 보호일세. 전장에서 전우를 보호하듯이 우리는 포세이큰의 이권을 보호해야만 하는 것이지.', '전사의 역할 중 하나는 보호일세. 전장에서 전우를 보호하듯이 우리는 포세이큰의 이권을 보호해야만 하는 것이지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1220, '오, 응급치료사 친구로군요. 당신의 여행에 도움이 된다면 무엇이든 기꺼이 가르쳐드리도록 하지요.', '오, 응급치료사 친구로군요. 당신의 여행에 도움이 된다면 무엇이든 기꺼이 가르쳐드리도록 하지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1221, '무슨 일이십니까? 도와드릴 일이 있습니까?', '무슨 일이십니까? 도와드릴 일이 있습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1225, '난 스톰윈드의 재건 사업을 도우러 아이언포지에서 왔지만 우리 얼라이언스 친구들에게 내 기술을 충분히 전수하고 난 후에는 이곳 일을 맡겨버리고 고향으로 돌아가고 싶어...', '난 스톰윈드의 재건 사업을 도우러 아이언포지에서 왔지만 우리 얼라이언스 친구들에게 내 기술을 충분히 전수하고 난 후에는 이곳 일을 맡겨버리고 고향으로 돌아가고 싶어...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1226, '이런, 한창 작업 중이었는데... 그래, 무슨 일이신지? 설마 아무 이유도 없이 그냥 한번 불러본 건 아닐테고...', '이런, 한창 작업 중이었는데... 그래, 무슨 일이신지? 설마 아무 이유도 없이 그냥 한번 불러본 건 아닐테고...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1228, '반갑습니다, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1231, '달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠습니다. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 특별히 찾으시는 물건이 있으십니까?', '달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠습니다. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 특별히 찾으시는 물건이 있으십니까?', '달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠습니다. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 특별히 찾으시는 물건이 있으십니까?', '달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠습니다. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 특별히 찾으시는 물건이 있으십니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1232, '달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠답니다. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 찾는 물건이 있으면 언제든지 말씀해 주시기 바랍니다.', '달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠답니다. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 찾는 물건이 있으면 언제든지 말씀해 주시기 바랍니다.', '달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠답니다. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 찾는 물건이 있으면 언제든지 말씀해 주시기 바랍니다.', '달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠답니다. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 찾는 물건이 있으면 언제든지 말씀해 주시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1233, '우리 상점의 물건들은 텔드랏실에서 가장 솜씨 좋은 장인들이 만든 것들로, 세계수의 나이트 엘프들과 이 땅의 인간들이 영광스러운 얼라이언스의 동맹으로서 관계가 발전함에 따라 그 우호의 표시로 칼림도어에서 아제로스까지 직접 수송한 것들입니다. 둘러보시다가 필요한 게 있으시면 주저 말고 말씀하시기 바랍니다.', '우리 상점의 물건들은 텔드랏실에서 가장 솜씨 좋은 장인들이 만든 것들로, 세계수의 나이트 엘프들과 이 땅의 인간들이 영광스러운 얼라이언스의 동맹으로서 관계가 발전함에 따라 그 우호의 표시로 칼림도어에서 아제로스까지 직접 수송한 것들입니다. 둘러보시다가 필요한 게 있으시면 주저 말고 말씀하시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1234, '달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠죠. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 오늘은 무슨 일로 오셨나요?', '달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠죠. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 오늘은 무슨 일로 오셨나요?', '달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠죠. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 오늘은 무슨 일로 오셨나요?', '달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠죠. 하지만 루칸 코르델과 다른 직업용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 오늘은 무슨 일로 오셨나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1235, '저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 손님, 무엇을 도와드릴까요?', '저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 손님, 무엇을 도와드릴까요?', '저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 손님, 무엇을 도와드릴까요?', '저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 손님, 무엇을 도와드릴까요?', '저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 손님, 무엇을 도와드릴까요?', '저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 손님, 무엇을 도와드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1236, '어서 오세요, 손님. 저희 상점은 스톰윈드 최고의 품질을 자랑하지요, 무엇을 도와드릴까요?', '어서 오세요, 손님. 저희 상점은 스톰윈드 최고의 품질을 자랑하지요, 무엇을 도와드릴까요?', '어서 오세요, 손님. 저희 상점은 스톰윈드 최고의 품질을 자랑하지요, 무엇을 도와드릴까요?', '어서 오세요, 손님. 저희 상점은 스톰윈드 최고의 품질을 자랑하지요, 무엇을 도와드릴까요?', '어서 오세요, 손님. 저희 상점은 스톰윈드 최고의 품질을 자랑하지요, 무엇을 도와드릴까요?', '어서 오세요, 손님. 저희 상점은 스톰윈드 최고의 품질을 자랑하지요, 무엇을 도와드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1237, '저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 무엇을 도와드릴까요?', '저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 무엇을 도와드릴까요?', '저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 무엇을 도와드릴까요?', '저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 무엇을 도와드릴까요?', '저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 무엇을 도와드릴까요?', '저희 상점은 스톰윈드에서 최고의 품질과 가격을 자랑합니다. 무엇을 도와드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1238, '엄격한 품질 점검을 거친 최고의 장비만을 취급하는 만큼, 정가 판매만 고집하고 있습니다. 값을 깎고 싶다면 고블린에게나 가보시는 게 좋겠습니다.', '엄격한 품질 점검을 거친 최고의 장비만을 취급하는 만큼, 정가 판매만 고집하고 있습니다. 값을 깎고 싶다면 고블린에게나 가보시는 게 좋겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1239, '엄격한 품질 기준을 통과한 최고의 장비만을 판매하는 만큼 에누리는 없으니, 값을 깎으려거든 고블린에게나 가보시오.', '엄격한 품질 기준을 통과한 최고의 장비만을 판매하는 만큼 에누리는 없으니, 값을 깎으려거든 고블린에게나 가보시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1240, '저희는 최고의 장비만을 취급합니다. 엄격한 품질 기준을 통과한 진짜 물건들입니다. 죄송하지만 깎아드릴 수는 없으니 흥정을 하시려거든 고블린에게나 가보시는 게 좋겠네요.', '저희는 최고의 장비만을 취급합니다. 엄격한 품질 기준을 통과한 진짜 물건들입니다. 죄송하지만 깎아드릴 수는 없으니 흥정을 하시려거든 고블린에게나 가보시는 게 좋겠네요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1241, '찬란한 빛이 당신의 길을 비추고 이끌어 주기를 바랍니다. 이쪽에 있을 테니 구경하시다가 도움이 필요하시면 부르시기 바랍니다.', '찬란한 빛이 당신의 길을 비추고 이끌어 주기를 바랍니다. 이쪽에 있을 테니 구경하시다가 도움이 필요하시면 부르시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1242, '찬란한 빛이 당신의 길을 비추고 이끌어 주기를 바랍니다. 이쪽에 있을 테니 구경하시다가 도움이 필요한 게 있으면 부르도록 하십시오.', '찬란한 빛이 당신의 길을 비추고 이끌어 주기를 바랍니다. 이쪽에 있을 테니 구경하시다가 도움이 필요한 게 있으면 부르도록 하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1243, '시장에 있는 인간들은 믿지 마세요. 노움이 건설한 지하철 덕분에 아이언포지에서 물건을 공수해오기가 생각보다 쉽답니다. 그러니까 수입 관세까지 붙여서 파는 상인이 있거든 그냥 돌아오세요. 제가 싸게 드리겠습니다.', '시장에 있는 인간들은 믿지 마세요. 노움이 건설한 지하철 덕분에 아이언포지에서 물건을 공수해오기가 생각보다 쉽답니다. 그러니까 수입 관세까지 붙여서 파는 상인이 있거든 그냥 돌아오세요. 제가 싸게 드리겠습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1249, '자, 80번 고리를 79번 구멍에 끼우면 쾅! 당연히 폭발하죠! 자, 내 물건들을 보여줄 테니, 구입하면 일단 릴리암에게 가서 사용법을 제대로 배워요. 폭발해서 눈썹 태워 먹지 않도록!', '자, 80번 고리를 79번 구멍에 끼우면 쾅! 당연히 폭발하죠! 자, 내 물건들을 보여줄 테니, 구입하면 일단 릴리암에게 가서 사용법을 제대로 배워요. 폭발해서 눈썹 태워 먹지 않도록!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1250, '어서 오십시오. 스톰윈드 은행에 오신 것을 환영합니다. 저희 은행은 생긴 이래로 단 한 건의 도난 사건도 발생한 적이 없습니다. 고객 만족을 위해 항상 최선을 다하겠습니다!', '어서 오십시오. 스톰윈드 은행에 오신 것을 환영합니다. 저희 은행은 생긴 이래로 단 한 건의 도난 사건도 발생한 적이 없습니다. 고객 만족을 위해 항상 최선을 다하겠습니다!', '어서 오십시오. 스톰윈드 은행입니다. 금융 업무뿐만 아니라 귀중품을 보관할 수 있습니다. 저희 은행에 보관함을 개설하셨나요, 손님?', '어서 오십시오. 스톰윈드 은행입니다. 금융 업무뿐만 아니라 귀중품을 보관할 수 있습니다. 저희 은행에 보관함을 개설하셨나요, 손님?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1252, '어서 오십시오. 고독한 은둔자 선술집입니다. 마법에 재능이 있는 친구들이 모여 열정을 불태우는 곳이죠. 아, 화염 마법으로 불을 지른다는 건 아닙니다. 그냥 회포를 푼다는 말씀입죠. 헤헤... 뭘 도와드릴까요, 손님?', '어서 오십시오. 고독한 은둔자 선술집입니다. 마법에 재능이 있는 친구들이 모여 열정을 불태우는 곳이죠. 아, 화염 마법으로 불을 지른다는 건 아닙니다. 그냥 회포를 푼다는 말씀입죠. 헤헤... 뭘 도와드릴까요, 손님?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1253, '내가 충고 한마디 해 드릴까? 어둠은 가까이하지 않는 게 좋을 것이오.', '내가 충고 한마디 해 드릴까? 어둠은 가까이하지 않는 게 좋을 것이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1254, '어서 오십시오. 돼지와 휘파람 선술집입니다! 술 한잔 들고 와서 앉으시죠. 술자리에서 친구란 많으면 많을수록 흥겨운 법이니까요!', '어서 오십시오. 돼지와 휘파람 선술집입니다! 술 한잔 들고 와서 앉으시죠. 술자리에서 친구란 많으면 많을수록 흥겨운 법이니까요!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1255, '저희 가게에서는 스톰윈드 각지에 싱싱한 꽃을 독점 공급하고 있습니다. 어디에나 잘 어울리고 동부 왕국 어디서도 찾을 수 없는 아름다운 꽃이죠. 천천히 둘러보시면서 꽃 향기에 흠뻑 취해보시는 게 어떨까요?', '저희 가게에서는 스톰윈드 각지에 싱싱한 꽃을 독점 공급하고 있습니다. 어디에나 잘 어울리고 동부 왕국 어디서도 찾을 수 없는 아름다운 꽃이죠. 천천히 둘러보시면서 꽃 향기에 흠뻑 취해보시는 게 어떨까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1256, '어서 오십시오. 오늘은 어디로 가시겠습니까, 손님? 몇 실버만 내시면 제 그리핀으로 천리마보다 더 빨리 목적지에 모셔다 드리겠습니다.', '어서 오십시오. 오늘은 어디로 가시겠습니까, 손님? 몇 실버만 내시면 제 그리핀으로 천리마보다 더 빨리 목적지에 모셔다 드리겠습니다.', '이 거대한 친구들은 걸어서는 갈 수 없는 길을 잘 알고 있지요. 신속하게 목적지에 모셔다 드리겠습니다. 가시는 동안 주위 경관이나 천천히 둘러보십시오.', '이 거대한 친구들은 걸어서는 갈 수 없는 길을 잘 알고 있지요. 신속하게 목적지에 모셔다 드리겠습니다. 가시는 동안 주위 경관이나 천천히 둘러보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1257, '목소리 낮추고 말 조심하시오. 이곳에서는 말 한마디만 잘못해도 큰일이 나는 수가 있거든. 뭐 도와드릴 일이라도 있나요?', '목소리 낮추고 말 조심하시오. 이곳에서는 말 한마디만 잘못해도 큰일이 나는 수가 있거든. 뭐 도와드릴 일이라도 있나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1258, '목소리 낮추고 말 조심하시오. 이곳에서는 말 한마디만 잘못해도 큰일이 나는 수가 있으니까요. 자, 뭐 도와드릴 일이라도 있습니까?', '목소리 낮추고 말 조심하시오. 이곳에서는 말 한마디만 잘못해도 큰일이 나는 수가 있으니까요. 자, 뭐 도와드릴 일이라도 있습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1259, '어서 오십시오. 스톰윈드 길드 사무소입니다. 무엇을 도와드릴까요?', '어서 오십시오. 스톰윈드 길드 사무소입니다. 무엇을 도와드릴까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1260, '스톰윈드 길드 사무소에 오신 것을 환영합니다. 어떤 업무를 도와드리면 되겠소이까?', '스톰윈드 길드 사무소에 오신 것을 환영합니다. 어떤 업무를 도와드리면 되겠소이까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1261, '그저 따뜻한 온기를 쬐면서 몸이나 녹이려고 대용광로까지 찾아온 건 아닐 테지. 어서 말해 보시오. 뭘 도와주면 되겠소?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1262, '손톱 밑에 때 하며 튼튼한 골격까지 척 보기에도 타고난 대장장이로군그래. 당신의 몸속에는 대장장이의 피가 흐르고 있는 것이야. 그렇다면, 기술을 배우러 온 것이겠군. 자, 망치를 들어 보시오. 뭘 가르쳐야 할지 한번 보겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1272, '어떤 물건을 찾으시나요?', '어떤 물건을 찾으시나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1291, '크룸이란 타우렌을 찾아가 보시는 게 좋겠습니다. 썬더 블러프 봉우리 하층 길드사무소에 가면 그를 찾을 수 있을 겁니다.', '크룸이란 타우렌을 찾아가 보시는 게 좋겠습니다. 썬더 블러프 봉우리 하층 길드사무소에 가면 그를 찾을 수 있을 겁니다.', '동족과의 우정은 아주 강력한 힘이 될 수 있습니다. 이런 일은 크룸이 도와 줄 수 있지요. 봉우리 하층, 승강기 옆에 있는 썬더 블러프 길드 사무소를 찾아가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1292, '썬더 블러프 은행은 봉우리 하층에 있습니다.', '썬더 블러프 은행은 봉우리 하층에 있습니다.', '속세의 소유물은 봉우리 하층에 있는 썬더 블러프 은행에서 떨쳐 버리도록 하십시오.', '속세의 소유물은 봉우리 하층에 있는 썬더 블러프 은행에서 떨쳐 버리도록 하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1293, '마을 중앙에 있는 토템 모양 건물의 계단 꼭대기로 올라가면 와이번 횃대를 찾을 수 있습니다.', '마을 중앙에 있는 토템 모양 건물의 계단 꼭대기로 올라가면 와이번 횃대를 찾을 수 있습니다.', '거대한 새를 타고 하늘을 날아오르는 건 참으로 멋진 일이지요. 와이번 횃대 꼭대기에서 탈을 찾으십시오. 당신이 가고자 하는 곳으로 보내 줄 겁니다.', '거대한 새를 타고 하늘을 날아오르는 건 참으로 멋진 일이지요. 와이번 횃대 꼭대기에서 탈을 찾으십시오. 당신이 가고자 하는 곳으로 보내 줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1294, '장로의 봉우리에 있는 장로의 전당에서 투락 룬토템을 찾아가 보시기 바랍니다.', '장로의 봉우리에 있는 장로의 전당에서 투락 룬토템을 찾아가 보시기 바랍니다.', '명예로운 자여, 장로의 봉우리에 있는 장로의 전당에서 투락 룬토템과 다른 드루이드들이 당신을 기다리고 있습니다.', '명예로운 자여, 장로의 봉우리에 있는 장로의 전당에서 투락 룬토템과 다른 드루이드들이 당신을 기다리고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1295, '아, 사냥꾼의 전당 쪽으로 가 보셔야 하겠군요. 수렵의 봉우리로 가시면 홀트 썬더혼과 같은 훌륭한 사냥꾼들을 만나볼 수 있을 겁니다.', '아, 사냥꾼의 전당 쪽으로 가 보셔야 하겠군요. 수렵의 봉우리로 가시면 홀트 썬더혼과 같은 훌륭한 사냥꾼들을 만나볼 수 있을 겁니다.', '모든 동물은 사냥꾼의 친구지요. 수렵의 봉우리 꼭대기에 있는 사냥꾼의 전당으로 가 보십시오.', '모든 동물은 사냥꾼의 친구지요. 수렵의 봉우리 꼭대기에 있는 사냥꾼의 전당으로 가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1296, '신비로운 마법의 추종자시로군요?! 흠, 그렇다면... 정기의 봉우리 아래 있는 예언의 웅덩이 근처로 가 보십시오.', '신비로운 마법의 추종자시로군요?! 흠, 그렇다면... 정기의 봉우리 아래 있는 예언의 웅덩이 근처로 가 보십시오.', '불쌍한 언데드들의 운명을 생각하면 아주 슬퍼지지요. 정기의 봉우리 밑에 있는 예언의 웅덩이에서 명상에 잠겨 있는 대마법사 심을 찾아가 보십시오.', '불쌍한 언데드들의 운명을 생각하면 아주 슬퍼지지요. 정기의 봉우리 밑에 있는 예언의 웅덩이에서 명상에 잠겨 있는 대마법사 심을 찾아가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1297, '신부 콥을 만나보셔야 하겠군요. 정기의 봉우리 아래 예언의 웅덩이 동굴에 있습니다.', '신부 콥을 만나보셔야 하겠군요. 정기의 봉우리 아래 예언의 웅덩이 동굴에 있습니다.', '언데드들은 종족이 겪고 있는 비극적인 상황에도 불구하고 여기까지 와서 우리를 돕고 있습니다. 우리도 그만큼 그들에게 도움이 되었으면 좋겠군요. 정기의 봉우리 밑에 있는 예언의 웅덩이 근처에서 신부 콥을 찾아보시기 바랍니다.', '언데드들은 종족이 겪고 있는 비극적인 상황에도 불구하고 여기까지 와서 우리를 돕고 있습니다. 우리도 그만큼 그들에게 도움이 되었으면 좋겠군요. 정기의 봉우리 밑에 있는 예언의 웅덩이 근처에서 신부 콥을 찾아보시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1298, '정기의 봉우리에 있는 정기의 전당은 주술사에게는 집과 같은 곳입니다. 그곳으로 가시면 훌륭한 주술사들을 만나실 수 있을 겁니다. 선조님의 보살핌이 있으시길.', '정기의 봉우리에 있는 정기의 전당은 주술사에게는 집과 같은 곳입니다. 그곳으로 가시면 훌륭한 주술사들을 만나실 수 있을 겁니다. 선조님의 보살핌이 있으시길.', '대지모신께서 당신의 부름에 응하실 것입니다. 정기의 봉우리에 있는 정기의 전당으로 가 보십시오.', '대지모신께서 당신의 부름에 응하실 것입니다. 정기의 봉우리에 있는 정기의 전당으로 가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1299, '우리처럼 제대로 된 전사 훈련을 받고 싶으신가요? 사냥꾼의 전당에 있는 사크 레이지토템을 만나면 도움을 받을 수 있을 겁니다.', '우리처럼 제대로 된 전사 훈련을 받고 싶으신가요? 사냥꾼의 전당에 있는 사크 레이지토템을 만나면 도움을 받을 수 있을 겁니다.', '강인한 신체와 영혼이 조화를 이뤘을 때 최강의 전사로 다시 태어나게 되는 것입니다! 사냥꾼의 전당에서 사크 레이지토템을 찾아가 전사로서의 당신의 새로운 운명을 발견하십시오.', '강인한 신체와 영혼이 조화를 이뤘을 때 최강의 전사로 다시 태어나게 되는 것입니다! 사냥꾼의 전당에서 사크 레이지토템을 찾아가 전사로서의 당신의 새로운 운명을 발견하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1300, '어떤 직업 상급자를 찾나?', '어떤 직업 상급자를 찾나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1301, '어떤 기술을 배우려고 하나?', '어떤 기술을 배우려고 하나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1302, '아주 재미있군요... 오크들은 인간 냄새가 역겹다 하고 인간들은 오크 냄새가 구역질 난다니 말이에요. 하지만 제겐 이 세계의 모든 종족이 같은 냄새를 풍겨요. 머리를 어지럽게 만드는 고약한 탐욕의 냄새.$B$B제 말이 맞지 않나요? 삶을 이끌고 결정하는 것들이 모두 욕심에서 비롯되지 않나요?$B$B그럼 될 대로 되라지. 고향에서 너무나 멀리 떨어진 이곳으로 저를 데려온 것이 탐욕이었으니 나를 다시 되돌려놓을 것도 탐욕이죠.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1303, '이 굼이샤를 도우러 되돌아온 거예요? 고통이란 건 의지력이 약해질 때만 느껴지죠. 아무리 뼈를 깎는 고통이라도... $B$B걱정하지 마세요. 다행히 이번 수집 일은 의지력 따위와는 상관없을 테니... 당신이 물건을 가져 오면 꼭 보답하겠어요. 주인을 기다리고 있는 제 물건들은 비록 자질구레하지만 분명 마음에 들 거예요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1332, '봉우리 중간층에 있는 베나의 연금술점에 가서 베나와 얘기해 보도록 하십시오. 그녀가 물약 제조 기술을 완벽히 터득할 수 있도록 도와줄 겁니다.', '봉우리 중간층에 있는 베나의 연금술점에 가서 베나와 얘기해 보도록 하십시오. 그녀가 물약 제조 기술을 완벽히 터득할 수 있도록 도와줄 겁니다.', '자연에서 구한 약초는 그것을 존중하는 마음으로 대할 때 우리의 강력한 동지가 되어 줄 것입니다. 봉우리 중간층에서 연금술 가게를 운영하고 있는 베나를 찾아가서 훈련을 더 받도록 하십시오.', '자연에서 구한 약초는 그것을 존중하는 마음으로 대할 때 우리의 강력한 동지가 되어 줄 것입니다. 봉우리 중간층에서 연금술 가게를 운영하고 있는 베나를 찾아가서 훈련을 더 받도록 하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1333, '망치와 모루를 잡고 뜨거운 용광로에서 일하는 법을 배우고 싶으시군요? 그렇다면 봉우리 하층의 연못가에서 대장간을 하고 있는 카른 스톤후프가 잘 가르쳐줄 수 있을 겁니다.', '망치와 모루를 잡고 뜨거운 용광로에서 일하는 법을 배우고 싶으시군요? 그렇다면 봉우리 하층의 연못가에서 대장간을 하고 있는 카른 스톤후프가 잘 가르쳐줄 수 있을 겁니다.', '다른 것들과 마찬가지로 금속도 자연과 균형을 고려해서 사용해야 합니다. 카른 스톤후프가 봉우리 하층에서 대장간을 하고 있으니 가서 그로부터 지혜를 구하십시오.', '다른 것들과 마찬가지로 금속도 자연과 균형을 고려해서 사용해야 합니다. 카른 스톤후프가 봉우리 하층에서 대장간을 하고 있으니 가서 그로부터 지혜를 구하십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1334, '썬더 블러프에 아스카 미스트러너만한 요리사는 없답니다. 봉우리 상층에 있는 그녀의 주방으로 가 보시면 만날 수 있을 겁니다. 음... 그녀의 요리 냄새가 여기까지 나는 것 같군요.nn이런... 슬슬 배가 고픈데요.', '썬더 블러프에 아스카 미스트러너만한 요리사는 없답니다. 봉우리 상층에 있는 그녀의 주방으로 가 보시면 만날 수 있을 겁니다. 음... 그녀의 요리 냄새가 여기까지 나는 것 같군요.nn이런... 슬슬 배가 고픈데요.', '자연에서 사냥한 동물은 한 군데도 버릴 곳이 없습니다. 그러므로 우리는 동물의 혼을 존중해 주어야 합니다. 아스카 미스트러너가 그 방법을 가르쳐줄 수 있습니다. 봉우리 상층에 있는 그녀의 주방을 찾아가 보십시오.', '자연에서 사냥한 동물은 한 군데도 버릴 곳이 없습니다. 그러므로 우리는 동물의 혼을 존중해 주어야 합니다. 아스카 미스트러너가 그 방법을 가르쳐줄 수 있습니다. 봉우리 상층에 있는 그녀의 주방을 찾아가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1335, '봉우리 중간층에 있는 돈스트라이더의 마법부여점을 찾아가 보시기 바랍니다. 테그가 기꺼이 도와줄 겁니다.', '봉우리 중간층에 있는 돈스트라이더의 마법부여점을 찾아가 보시기 바랍니다. 테그가 기꺼이 도와줄 겁니다.', '마법부여 기술은 자연의 중심에 있는 파괴와 창조의 순환을 보여 주지요. 봉우리 중간층, 돈스트라이더의 마법부여점에 있는 테그가 가르쳐 줄 겁니다.', '마법부여 기술은 자연의 중심에 있는 파괴와 창조의 순환을 보여 주지요. 봉우리 중간층, 돈스트라이더의 마법부여점에 있는 테그가 가르쳐 줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1336, '응급치료는 배워놓으면 아주 좋은 기술이랍니다. 저도 전쟁 중에 그것 덕분에 여러 번 목숨을 건졌답니다. 정기의 봉우리에 있는 정기의 치료소에 가시면 판드 스톤바인더가 자신의 목숨을 스스로 구하는 방법을 가르쳐줄 겁니다.', '응급치료는 배워놓으면 아주 좋은 기술이랍니다. 저도 전쟁 중에 그것 덕분에 여러 번 목숨을 건졌답니다. 정기의 봉우리에 있는 정기의 치료소에 가시면 판드 스톤바인더가 자신의 목숨을 스스로 구하는 방법을 가르쳐줄 겁니다.', '삶이란 투쟁이고 죽지 않을 정도의 상처는 오히려 몸을 강하게 만든다는 말이 언제나 옳은 것은 아닙니다. 상처가 쉽게 아물지 않을 때도 있는 법이지요. 그래서 붕대가 필요한 것입니다. 정기의 봉우리에 있는 판드 스톤바인더가 응급치료를 가르쳐줄 수 있습니다.', '삶이란 투쟁이고 죽지 않을 정도의 상처는 오히려 몸을 강하게 만든다는 말이 언제나 옳은 것은 아닙니다. 상처가 쉽게 아물지 않을 때도 있는 법이지요. 그래서 붕대가 필요한 것입니다. 정기의 봉우리에 있는 판드 스톤바인더가 응급치료를 가르쳐줄 수 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1337, '낚시를 배우시려고요? 멀고어에는 남부 칼림도어에서 으뜸가는 낚시터가 여러 곳 있고 봉우리 상층에 있는 산꼭대기 낚시용품점에는 온갖 낚시 장비가 다양하게 구비되어 있습니다.nn카 미스트러너를 만나 제가 보내더라고 전해주세요!', NULL, '봉우리 상층, 산꼭대기 낚시용품점에 있는 카 미스트러너를 찾아가 보십시오. 요리에 쓸 물고기를 낚으면서 내면의 평화와 고요함을 찾는 법을 가르쳐줄 겁니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1338, '조화의 약초상점에 있는 코민 윈터후프를 찾아가 보셔야겠습니다. 그는 봉우리 중간층에 가시면 만나실 수 있답니다.', '조화의 약초상점에 있는 코민 윈터후프를 찾아가 보셔야겠습니다. 그는 봉우리 중간층에 가시면 만나실 수 있답니다.', '자연은 우리가 필요로 하는 모든 것을 제공합니다. 봉우리 중간층 조화의 약초상점에 있는 코민 윈터후프를 찾아가 보십시오.', '자연은 우리가 필요로 하는 모든 것을 제공합니다. 봉우리 중간층 조화의 약초상점에 있는 코민 윈터후프를 찾아가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1339, '봉우리 중간층에 썬더 블러프 갑옷 상점에 있는 우나를 찾아가 보시기 바랍니다.', '봉우리 중간층에 썬더 블러프 갑옷 상점에 있는 우나를 찾아가 보시기 바랍니다.', '적의 가죽을 이용해 자신을 몸을 보호할 수 있다니... 가죽세공술을 익히고 싶으시면 봉우리 중간층에 있는 썬더 블러프 갑옷 상점에서 우나를 찾아보십시오.', '적의 가죽을 이용해 자신을 몸을 보호할 수 있다니... 가죽세공술을 익히고 싶으시면 봉우리 중간층에 있는 썬더 블러프 갑옷 상점에서 우나를 찾아보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1340, '봉우리 하층에 있는 스톤후프 지질연구소로 가십시오. 브렉 스톤후프가 귀한 광석이나 보석을 캐내는 방법을 가르쳐 줄 겁니다.', '봉우리 하층에 있는 스톤후프 지질연구소로 가십시오. 브렉 스톤후프가 귀한 광석이나 보석을 캐내는 방법을 가르쳐 줄 겁니다.', '대지모신은 여러 가지 비밀을 간직하고 있는데, 브렉 스톤후프의 도움을 얻으면 일부라도 발견할 수 있을 것입니다. 봉우리 하층에 있는 스톤후프 지질연구소로 가 보십시오.', '대지모신은 여러 가지 비밀을 간직하고 있는데, 브렉 스톤후프의 도움을 얻으면 일부라도 발견할 수 있을 것입니다. 봉우리 하층에 있는 스톤후프 지질연구소로 가 보십시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1341, '썬더 블러프 최고의 재봉사, 테파를 찾아가 보도록 하시기 바랍니다. 봉우리 중간층에 있는 썬더 블러프 갑옷 상점에 만나실 수 있습니다.', '썬더 블러프 최고의 재봉사, 테파를 찾아가 보도록 하시기 바랍니다. 봉우리 중간층에 있는 썬더 블러프 갑옷 상점에 만나실 수 있습니다.', '부족에게 옷을 제공하는 것은 다른 어떤 일보다도 중요하죠. 썬더 블러프 갑옷 상점에서 테파를 찾아보십시오. 바느질에는 선천적인 소질이 있지요.', '부족에게 옷을 제공하는 것은 다른 어떤 일보다도 중요하죠. 썬더 블러프 갑옷 상점에서 테파를 찾아보십시오. 바느질에는 선천적인 소질이 있지요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1343, '무두질이라면 무란타에게 배울 수 있을 겁니다. 봉우리 중간층에 있는 썬더 블러프 갑옷 상점 앞에서 그녀를 찾을 수 있을 겁니다.', '무두질이라면 무란타에게 배울 수 있을 겁니다. 봉우리 중간층에 있는 썬더 블러프 갑옷 상점 앞에서 그녀를 찾을 수 있을 겁니다.', '금속 조각을 잘만 활용하면 낭비가 적어지고 대지모신에게 더욱 가까워질 수 있습니다. 무란타가 그 비법을 알려 줄 겁니다. 봉우리 중간층에 있는 썬더 블러프 갑옷 상점 앞에서 찾아보시기 바랍니다.', '금속 조각을 잘만 활용하면 낭비가 적어지고 대지모신에게 더욱 가까워질 수 있습니다. 무란타가 그 비법을 알려 줄 겁니다. 봉우리 중간층에 있는 썬더 블러프 갑옷 상점 앞에서 찾아보시기 바랍니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1351, '이 저주받은 땅의 짐승들은 지금까지 자연에서 한 번도 본 적 없는 기이한 성질을 나타내오.$B$B우리는 어둠의 문이 열리면서 방출된 에너지가 짐승의 육체와 결합해 지금의 형태로 변형된 것으로 본다오.$B$B두려워 할 만한 짐승들임에는 분명하지만 우리 연구에 상당히 쓸모가 있을 것이라 생각하오.$B$B짐승들 연구에 도움을 주지 않겠소, 용감한 $c|1이여;여;?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1371, '드라지알 오빠는 저주받은 땅에 서식하는 야생동물들의 육체적 특성을 주로 분석하지만, 저는 지적이고 영적인 면을 더 집중적으로 연구합니다.$B$B그 짐승들이 보기 드물게 강한 힘과 민첩성, 체력을 가진 것은 사실이지만 그중 일부는 육체에 구속되지 않은 높은 지능과 재생 능력도 보유하고 있답니다.$B$B$R|1이여;여;, 혹시 제 연구에 도움을 주실 생각은 없나요?', '드라지알 오빠는 저주받은 땅에 서식하는 야생동물들의 육체적 특성을 주로 분석하지만, 저는 지적이고 영적인 면을 더 집중적으로 연구합니다.$B$B그 짐승들이 보기 드물게 강한 힘과 민첩성, 체력을 가진 것은 사실이지만 그중 일부는 육체에 구속되지 않은 높은 지능과 재생 능력도 보유하고 있답니다.$B$B$R|1이여;여;, 혹시 제 연구에 도움을 주실 생각은 없나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1391, '그렇게 작은 지역에 그토록 많은 죽음과 절망이 도사리고 있다는 게 상상조차 안 되겠지만, 저 늪에서 한 발짝만 넘어서도 혼돈과 파괴로 물든 땅이 있지.$B$B모험가 친구, 발밑을 조심하시오. 저주받은 땅은 당신보다 훨씬 강한 자들의 마지막 안식처니까 말이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1392, '스랄 직속 부대... 사람들은 우리를 이렇게 불렀지. 스랄 님의 병사 중 가장 실력이 뛰어나고 충성스러운 스무 명의 병사로 이뤄진 최정예부대였소.$B$B오그리마에서 명령서가 오기를 기다리는 동안 나는 저주받은 땅의 경계인 이곳에 야영지를 지으라고 지시했소. 몇 주가 지나도록 대족장님에게 아무런 소식이 없어 모두 불안해했지.$B$B나는 벌을 받은 거요, $n. 젊고 의욕에 넘쳤던 나는 아무것도 두려울 게 없었지. 대대를 이끌고 저주받은 땅으로 행군하기로', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1411, '후회... 그것이 지금 내게 남은 전부요. 잘못된 판단 하나가 끔찍한 결과를 낳고 말았소. 명령서를 기다렸더라면 좋았을 것을. 그랬더라면 저주받은 땅에서 우리를 기다리고 있던 공포에 대해 알 수도 있었을 텐데! 어쩌면 다른 곳으로 파견되었을지도 모르지. 결국 내 잘못이었소. 모든 게 내 잘못이었소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1451, '내 생애에서 절정을 달리던 시기에 실패를 했다면 믿으시겠소? 그때가 내 평생 가장 눈부셨던 동시에 어두웠던 때라오.$B$B우리를 무자비하게 침략했던 세력으로부터 도망쳐 나올 때 내 귀에는 우리 병사들의 참혹한 비명 소리와 세차게 뛰는 내 심장의 빠른 고동소리만 들렸소.$B$B얼마 후 부하들을 구하고 명예를 회복하겠다는 기대를 안고 저주받은 땅으로 되돌아왔소. 하지만 붙잡혀서 구타당하다 죽고 말았지.$B$B그때 고문을 받으면서 알게 된 사실은 정말이지 끔', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1452, '나를 붙잡은 녀석들은 차마 말로는 표현하지 못할 정도로 잔인했소. 부관 키리스와 나를 번갈아 고문하면서 괴로워하는 모습을 서로 강제로 지켜보게 하였소. 유독 고문이 심했던 어느 날인가 키리스는 잠잠한 틈을 타 우리 부하들에게 벌어진 끔찍한 사건과 그들을 해방시키기 위해 그가 세운 계획을 말해주었소.$B$B나의 부하들은 키리스와 내가 겪었던 고통보다, 아니 죽음보다도 더 끔찍한 운명에 괴로워했더군...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1453, '당신이나 나나 영혼이 육체에서 억지로 찢겨나갈 때의 고통은 상상도 할 수 없을 거요. 우리 병사들은 완전히 죽은 것도, 살아있는 것도 아닌 상태... 그 상태로 이 세계에 그들을 묶어둔 자들의 노예로 살아가야 했던 거요.$B$B바로 이 땅을 지배하는 악마 군주 라젤리크의 노예가 돼버린 것이오. 라젤리크는 그중 아홉 명을 어둠의 문 근처 봉인석에 배치하고 있소. 그리고 나머지 아홉은 자기 부하들에게 나눠주었소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1454, '어둠혈맹 대마법사 알리스타즈에게 세 명, 어둠혈맹 흑마법사인 여군주 세바인에게 세 명, 그리고 이 저주받은 땅의 우레망치 오우거를 다스리는 파괴자 그롤에게 나머지 세 명을 주었소.$B$B당신도 이미 알고 있겠지만, 영혼이 없는 육체는 죽일 수 없소. 이제 내 부하들은 불로불사의 전투 부대가 되어 악의 명령에 따르고 있소. 그나마 다행인 것은 봉인석으로 이동할 수 있는 거리 내에서만 움직일 수 있다는 거요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1455, '바로 그 봉인석을 파괴해야 우리 부하들을 해방킬 수 있소! 아까도 말했지만 키리스에게는 계획이 있었소.$B$B라젤리크의 하수인에겐 모두 약점이 있소. 봉인석 근처에 있는 육신을 계속 공격하면 하수인들이 분열 상태에 가까워진다오. 바로 그때 봉인석을 공격해야 하오. 하수인들이 다시 깨어나면 아무리 공격해도 소용이 없으니 서둘러서 봉인석을 파괴해야 하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1456, '정말로 당신 혼자서 해낼 수 있다면 얼마나 좋겠소. 하지만 혼자 힘으로 라젤리크와 그 부하들을 상대한다는 것은 무리요.$B$B영웅이 되고자 모험을 하는 이들을 모아 우리 부하들을 끝이 없는 고통에서 해방시켜 주시오! 모두 18개의 돌을 부수어야만 하오.$B$B용맹스럽게 싸우다 명예롭게 죽으시오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1471, '연금술 재료가 필요하시군요? 아니면 다른 볼일로 오셨나요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1493, '사막에서 산다는 것은 참 고된 일이야! 이런 찌는 듯한 날씨에 횃불까지 들고 서 있으려니 정말 덥고 목이 마르는군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1511, '도와줘!$B$B날 여기서 빠져나가게 해주면 줄파락의 두목이 있는 곳으로 통하는 문을 폭파해 버릴 수 있다고!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1513, '트롤을 더 많이 처치해야 해! 충분히 처치하면 트롤 두목에게로 통하는 문을 폭파해 주겠어!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1514, '고마워, $n. 자네가 나타나지 않았더라면 난 분명 이미 죽은 목숨이었을 거야! 이제 우리 앞에 있는 저 문만 날려 버리면 트롤 두목이 기다리고 있을 거라고...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1515, '도와주시오! 나는 일행과 함께 트롤들에게 붙잡혔소. 놈들은 우리를 희생 제물로 바치려 하고 있소!$B$B여기서 빠져나가게 해주면 당신이 원하는 것은 뭐든지 해주겠소.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1516, '떠들고 있을 시간이 없소! 저 트롤 녀석들을 처치해야 탈출할 수 있단 말이오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1517, '고맙소, $n. 당신 없이는 빠져나오지 못했을 거요. 아, 전에 구해주면 보답을 하겠다고 했던가? 뭐... 그런 건 없었던 일로 하죠!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1519, '안녕하세요! 모험을 즐기시는 분이시군요. 혹시 도전할 만한 일을 찾고 있다면 한 가지 제안이 있어요.$B$B지금 저는 열심히 드루이드들을 돕고 있어요. 제가 발명한 고성능 자동부화기로 히포그리프들을 구하려고요. 히포그리프들에게 페랄라스의 폐허에 사는 골두니 오우거들이 나쁜 영향을 미치고 있습니다. 때문에 그 수가 점점 줄어들고 있어요.$B$B그래서 저는 여러 종류의 알을 모은답니다. 저를 도와 알을 좀 찾아주시겠습니까?', '안녕하세요! 모험을 즐기시는 분이시군요. 혹시 도전할 만한 일을 찾고 있다면 한 가지 제안이 있어요.$B$B지금 저는 열심히 드루이드들을 돕고 있어요. 제가 발명한 고성능 자동부화기로 히포그리프들을 구하려고요. 히포그리프들에게 페랄라스의 폐허에 사는 골두니 오우거들이 나쁜 영향을 미치고 있습니다. 때문에 그 수가 점점 줄어들고 있어요.$B$B그래서 저는 여러 종류의 알을 모은답니다. 저를 도와 알을 좀 찾아주시겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1521, '서쪽에 있는 페랄라스라는 곳에서 나이트 엘프들의 오랜 친구인 히포그리프들이 위험에 처해있다고 들었어요.$B$B남쪽의 이실디엔 폐허에서 알을 구해 오세요. 가져온 알은 고성능 자동부화기에 넣어 보면 부화할 수 있는지 알 수 있답니다. 제가 부화할 수 있는 알들만 드루이드들에게 보낼 거예요. 골두니 오우거의 사악한 마법을 피해 건강한 히포그리프로 자랄 수 있도록 말이지요.$B$B구해 온 알들 중 일부는 상태가 좋지 않아서 절대 부화하지 않는다는 걸 알아두세', '서쪽에 있는 페랄라스라는 곳에서 나이트 엘프들의 오랜 친구인 히포그리프들이 위험에 처해있다고 들었어요.$B$B남쪽의 이실디엔 폐허에서 알을 구해 오세요. 가져온 알은 고성능 자동부화기에 넣어 보면 부화할 수 있는지 알 수 있답니다. 제가 부화할 수 있는 알들만 드루이드들에게 보낼 거예요. 골두니 오우거의 사악한 마법을 피해 건강한 히포그리프로 자랄 수 있도록 말이지요.$B$B구해 온 알들 중 일부는 상태가 좋지 않아서 절대 부화하지 않는다는 걸 알아두세', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1569, '반갑습니다, $n.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1571, '안녕하세요! 찾고 계신 물건이 제 가게에서 안 보이시나요? 말씀만 하시면 제가 꼭 구해다 드리겠습니다!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1597, '아이언포지에서 이렇게 멀리 떨어진 곳에서는 대장장이를 보는 일이 드문데... 뭘 도와주면 좋겠습니까?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1598, '나는 머리 위에 튼튼한 화강암 천장이 없으면 편히 쉴 수가 없답니다. 머리 위에 별이 어찌나 많은지 등골이 서늘할 정도라니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1599, '이 정도는 돼야 입을 만한 쇳덩어리라고 할 수 있지. 모양새에 기능까지 골고루 갖추다니 놀랐습니다. 이만한 건 예전에 딱한 번 본 적이 있는데 대용광로에 있는 장인인 그룸누스 스틸셰이퍼가 만든 것이었지요. 분명 그 친구는 그때보다 솜씨가 더 늘었을 거요. 당신에게 한 수 가르쳐 줄 수도 있겠군요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1600, '아이언포지 한복판에 있는 대용광로로 가 보십시오. 그는 그곳에서 우리 종족의 다른 훌륭한 장인들과 함께 일하고 있습니다.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1605, '내 작업장에 온 걸 환영하네, 대장장이 친구. 한 가지 작은 비밀을 가르쳐 주지. 이 세상에 어느 누구도 믿을 자가 없다는 거야. 남자든, 여자든, 동물이든지 할 것 없이 모두... 하지만 단 한 가지 믿을 게 있다면, 바로... 강철이라네.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1606, '내 작업장에 뭘 찾으러 온 건가? 훈련을 받고 싶나? 아니면 강철의 비밀이라도 캐러 왔나? 아니면 가열로의 신비를 파헤치러? 어서 말해 보게나!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1609, '오그리마에 있는 명예의 골짜기로 가시오. 그곳에서 그녀는 남편과 두 딸이 함께 살고 있소. 실력이 뛰어난 대장장이는 많지만, 정령들이 말하길 당신을 가장 잘 지도할 사람은 그녀뿐이라는군.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1610, '이제 솜씨는 내가 결코 따라갈 수가 없구려. 강철에 영혼의 숨결을 불어넣어 자신을 보호할 수 있으니 말이오. 제자가 스승을 능가했으니 이제는 더 가르칠 것이 없소이다. 계속 가르침을 받을 수 있는 곳으로 보내겠소. 오그리마에 있는 샤이스 스틸퓨리를 찾아가시오. 그는 내가 아는 최고의 방어구제작자이니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1611, '모든 것에는 영혼이 있소. 영혼의 소리에 귀 기울이는 법을 배우면 사물의 모습을 당신이 원하는 대로 바꿀 수 있지. 대장장이 일이란 금속을 쳐서 당신이 원하는 모양을 억지로 만들어 내는 게 아니오. 강철 속에 살아 숨 쉬는 영혼의 소리에 귀를 기울여 그 영혼이 취하려는 모습으로 인도하는 것이지...', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1615, '당신은 지식을 갈구하는 자로 보이는군. 가열로와 망치 다루는 법을 배우고 싶은 것이겠지. 대장장이의 길을 걸어가는 데 내가 도움을 줄 수 있을 것 같소. 하지만 먼저 영혼의 존재를 인정하고 그 부름에 귀를 기울여야 하오.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1616, '명예의 골짜기에서 그녀와 그녀의 일족을 만날 수 있을 테니 오그리마로 가게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1617, '$n, 자네가 만드는 방어구라면 아무리 날카로운 도끼날이라도 모두 받아 낼 수 있을 거야. 흔하게 볼 수 있는 솜씨가 아니라 정말 놀랍군. 샤이스 스틸퓨리라는 오크를 찾아가 보게. 지금 천벌이나 받을 드워프들의 요새 바깥에 머물고 있지만, 방어구 하나는 최고로 훌륭하지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1618, '자네가 만드는 검날이 적의 복부를 꿰뚫기에 부족함이 없겠나? 무기의 날을 더욱 날카롭게 다듬는 법을 가르쳐주지.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1619, '대장장이가 되고 싶나? 단숨에 적을 가를 만큼 날카로운 검을 만들고 싶은가? 살짝 대기만 해도 목표물을 완전히 부숴 버릴 망치를 만들고 싶은 게로군. 도와주지. 그 무기로 갚아야 할 원한이 있다면 더더욱!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1620, '오크의 도시, 오그리마로 가게. 명예의 골짜기에 전설의 무기점이라는 곳이 있다네. 그곳에서 그를 찾아보도록 하게.', '오크의 도시, 오그리마로 가게. 명예의 골짜기에 전설의 무기점이라는 곳이 있다네. 그곳에서 그를 찾아보도록 하게.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1621, '$n, 아주 날카로운 검을 만들 줄 아는군. 바위라도 베어낼 수 있을 정도로 날카로운... 하지만 그보다 더 나은 것들을 본 적이 있다네. 바로 켈그룩 블러드액스라는 오크가 만든 것. 가서 그가 가르쳐 주는 건 모두 배우도록.', '$n, 아주 날카로운 검을 만들 줄 아는군. 바위라도 베어낼 수 있을 정도로 날카로운... 하지만 그보다 더 나은 것들을 본 적이 있다네. 바로 켈그룩 블러드액스라는 오크가 만든 것. 가서 그가 가르쳐 주는 건 모두 배우도록.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1633, '대용광로에 또 왔군, $n. 반갑소. 이 늙은 드워프를 보러 온 건가, 아니면 다음 훈련을 받을 준비가 되어서 온 것이오?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1634, '좋은 강철이군, $n. 망치를 들고 이리 와 보게. 전설의 무기를 만드는 비법을 가르쳐 줄 테니까.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1635, '뭔가? 일하느라 바쁜 거 모르겠나?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1637, '더 배우러 온 건가, $n? 더 가까이 와보게. 준비가 되었나 보겠어.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1638, '여행은 어땠나요, $n? $g수미와 투미가 당신을 보고 싶어 했어요. 다 배우면 가서 인사라도 나누세요:당신의 모험 얘기를 전해 들었어요. 꽤 바쁜 나날을 보낸 것 같더군요;. 자, 이곳을 떠나 있던 동안 뭘 배웠는지 한번 볼까요?', '여행은 어땠나요, $n? $g수미와 투미가 당신을 보고 싶어 했어요. 다 배우면 가서 인사라도 나누세요:당신의 모험 얘기를 전해 들었어요. 꽤 바쁜 나날을 보낸 것 같더군요;. 자, 이곳을 떠나 있던 동안 뭘 배웠는지 한번 볼까요?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1640, '난 실력이 없는 대장장이들은 훈련시키지 않는답니다. 쓸 만한 물건을 만들 실력을 갖췄다 싶을 때 다시 오도록 하세요.', '난 실력이 없는 대장장이들은 훈련시키지 않는답니다. 쓸 만한 물건을 만들 실력을 갖췄다 싶을 때 다시 오도록 하세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1641, '재능이 있군요, $n. 자, 연습이 많이 필요하니 망치와 그 조각들을 좀 가지고 오세요.', '재능이 있군요, $n. 자, 연습이 많이 필요하니 망치와 그 조각들을 좀 가지고 오세요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1643, '지지직!$B$B보안 수준 알파 터미널인 행렬 천공기록기 3005-A에 오신 것을 환영합니다.$B$B터미널 기능을 이용하시려면 백색 천공 카드가 있어야 합니다.nn01000100 01101111 01110111 01101110 00100000 01110111 01101001 01110100 01101000 00100000 01110100 01101000 01100101 00100000 01101000 01101111 01110010 01100100 011', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1644, '흰색 보안 카드 삽입 성공.$B$B보안 수준 베타 유닛 적용 중.nn01010000 01101100 01100001 01111001 00100000 01110100 01101000 01100101 00100000 01010111 01100001 01110010 01100011 01100001 01110010 01100110 01110100 00100000 01110010 01101111 01101100 01100101 01110000 01101100 0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(1646, '골두니 오우거 부족은 페랄라스의 숲 상당 부분을 지배하고 있습니다. 그들의 사악한 마법이 주위의 자연에 스며들어 주변 환경은 물론 그곳에 사는 생명체들에게도 해를 끼치고 있답니다.$B$B혹시 페랄라스로 갈 생각이라면 이 오우거들을 조심하세요. 상당히 간악한 데다 강력한 어둠의 마법을 부릴 줄 아는 녀석들이 많으니까요.', '골두니 오우거 부족은 페랄라스의 숲 상당 부분을 지배하고 있습니다. 그들의 사악한 마법이 주위의 자연에 스며들어 주변 환경은 물론 그곳에 사는 생명체들에게도 해를 끼치고 있답니다.$B$B혹시 페랄라스로 갈 생각이라면 이 오우거들을 조심하세요. 상당히 간악한 데다 강력한 어둠의 마법을 부릴 줄 아는 녀석들이 많으니까요.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
