-- Korean locale additions for `npc_text_locale`.
-- Update existing rows and insert missing rows only when the parent exists.
-- Preserve existing Korean text and other locales.
DROP TEMPORARY TABLE IF EXISTS `_koKR_stage_npc_text_locale`;
CREATE TEMPORARY TABLE `_koKR_stage_npc_text_locale` (
    `ID` INT UNSIGNED NOT NULL,
    `Text0_0` LONGTEXT NULL,
    `Text0_1` LONGTEXT NULL,
    `Text1_0` LONGTEXT NULL,
    `Text1_1` LONGTEXT NULL,
    `Text2_0` LONGTEXT NULL,
    `Text2_1` LONGTEXT NULL,
    `Text3_0` LONGTEXT NULL,
    `Text3_1` LONGTEXT NULL,
    `Text4_0` LONGTEXT NULL,
    `Text4_1` LONGTEXT NULL,
    `Text5_0` LONGTEXT NULL,
    `Text5_1` LONGTEXT NULL,
    `Text6_0` LONGTEXT NULL,
    `Text6_1` LONGTEXT NULL,
    `Text7_0` LONGTEXT NULL,
    `Text7_1` LONGTEXT NULL,
    PRIMARY KEY (`ID`)
) ENGINE=InnoDB;











UPDATE `npc_text_locale` AS `l`
INNER JOIN `_koKR_stage_npc_text_locale` AS `s` ON `l`.`ID` = `s`.`ID` AND `l`.`Locale` = 'koKR'
INNER JOIN `npc_text` AS `p` ON `p`.`ID` = `s`.`ID`
SET `l`.`Text0_0` = IF(`s`.`Text0_0` IS NOT NULL AND (`l`.`Text0_0` IS NULL OR `l`.`Text0_0` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Text0_0`, `l`.`Text0_0`),
    `l`.`Text0_1` = IF(`s`.`Text0_1` IS NOT NULL AND (`l`.`Text0_1` IS NULL OR `l`.`Text0_1` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Text0_1`, `l`.`Text0_1`),
    `l`.`Text1_0` = IF(`s`.`Text1_0` IS NOT NULL AND (`l`.`Text1_0` IS NULL OR `l`.`Text1_0` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Text1_0`, `l`.`Text1_0`),
    `l`.`Text1_1` = IF(`s`.`Text1_1` IS NOT NULL AND (`l`.`Text1_1` IS NULL OR `l`.`Text1_1` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Text1_1`, `l`.`Text1_1`),
    `l`.`Text2_0` = IF(`s`.`Text2_0` IS NOT NULL AND (`l`.`Text2_0` IS NULL OR `l`.`Text2_0` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Text2_0`, `l`.`Text2_0`),
    `l`.`Text2_1` = IF(`s`.`Text2_1` IS NOT NULL AND (`l`.`Text2_1` IS NULL OR `l`.`Text2_1` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Text2_1`, `l`.`Text2_1`),
    `l`.`Text3_0` = IF(`s`.`Text3_0` IS NOT NULL AND (`l`.`Text3_0` IS NULL OR `l`.`Text3_0` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Text3_0`, `l`.`Text3_0`),
    `l`.`Text3_1` = IF(`s`.`Text3_1` IS NOT NULL AND (`l`.`Text3_1` IS NULL OR `l`.`Text3_1` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Text3_1`, `l`.`Text3_1`),
    `l`.`Text4_0` = IF(`s`.`Text4_0` IS NOT NULL AND (`l`.`Text4_0` IS NULL OR `l`.`Text4_0` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Text4_0`, `l`.`Text4_0`),
    `l`.`Text4_1` = IF(`s`.`Text4_1` IS NOT NULL AND (`l`.`Text4_1` IS NULL OR `l`.`Text4_1` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Text4_1`, `l`.`Text4_1`),
    `l`.`Text5_0` = IF(`s`.`Text5_0` IS NOT NULL AND (`l`.`Text5_0` IS NULL OR `l`.`Text5_0` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Text5_0`, `l`.`Text5_0`),
    `l`.`Text5_1` = IF(`s`.`Text5_1` IS NOT NULL AND (`l`.`Text5_1` IS NULL OR `l`.`Text5_1` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Text5_1`, `l`.`Text5_1`),
    `l`.`Text6_0` = IF(`s`.`Text6_0` IS NOT NULL AND (`l`.`Text6_0` IS NULL OR `l`.`Text6_0` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Text6_0`, `l`.`Text6_0`),
    `l`.`Text6_1` = IF(`s`.`Text6_1` IS NOT NULL AND (`l`.`Text6_1` IS NULL OR `l`.`Text6_1` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Text6_1`, `l`.`Text6_1`),
    `l`.`Text7_0` = IF(`s`.`Text7_0` IS NOT NULL AND (`l`.`Text7_0` IS NULL OR `l`.`Text7_0` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Text7_0`, `l`.`Text7_0`),
    `l`.`Text7_1` = IF(`s`.`Text7_1` IS NOT NULL AND (`l`.`Text7_1` IS NULL OR `l`.`Text7_1` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Text7_1`, `l`.`Text7_1`);

SELECT `s`.`ID`, 'koKR', `s`.`Text0_0`, `s`.`Text0_1`, `s`.`Text1_0`, `s`.`Text1_1`, `s`.`Text2_0`, `s`.`Text2_1`, `s`.`Text3_0`, `s`.`Text3_1`, `s`.`Text4_0`, `s`.`Text4_1`, `s`.`Text5_0`, `s`.`Text5_1`, `s`.`Text6_0`, `s`.`Text6_1`, `s`.`Text7_0`, `s`.`Text7_1`
FROM `_koKR_stage_npc_text_locale` AS `s`
INNER JOIN `npc_text` AS `p` ON `p`.`ID` = `s`.`ID`
LEFT JOIN `npc_text_locale` AS `l` ON `l`.`ID` = `s`.`ID` AND `l`.`Locale` = 'koKR'
WHERE `l`.`ID` IS NULL;

DROP TEMPORARY TABLE `_koKR_stage_npc_text_locale`;
